// Send an outbound email from the EmailPage composer. Free-form (subject +
// body), optionally attached to a reservation for continuity. The
// buildCustomEmail template wraps the body in the branded HTML shell — the
// same one used by /reservations/:id/send-custom-email so both flows look
// identical to the recipient.
app.post('/email/send', authenticate, requirePermission('reservations:full'), async (req, res) => {
    try {
        const { to, subject, body, reservation_id, in_reply_to } = req.body || {};
        const toEmail = typeof to === 'string' ? to.trim() : '';
        const subj = typeof subject === 'string' ? subject.trim() : '';
        const bod = typeof body === 'string' ? body.trim() : '';
        if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(toEmail)) {
            return res.status(400).json({ error: 'Destinatario email non valido' });
        }
        if (!subj || subj.length > 200) return res.status(400).json({ error: 'Oggetto richiesto (max 200)' });
        if (!bod || bod.length > 5000) return res.status(400).json({ error: 'Corpo richiesto (max 5000)' });
        if (!(await isSmtpConfigured(req.tenantId!))) {
            return res.status(503).json({ error: 'SMTP non configurato — vai in Impostazioni' });
        }
        // Reservation_id from the client may be stale (thread summary points
        // to a reservation that got deleted between fetch and send). If the
        // row no longer exists, clear the FK so the INSERT doesn't blow up —
        // the email still lands in the thread, just without the reservation
        // link. The composer prefill (customer_name) collapses to "cliente".
        let reservationId: number | null = Number.isFinite(Number(reservation_id))
            ? Math.trunc(Number(reservation_id))
            : null;
        let customerName: string | null = null;
        if (reservationId != null) {
            const r = await queryWithRetry(
                // Un id di un altro tenant equivale a inesistente: l'email
                // parte comunque, ma senza aggancio alla prenotazione altrui.
                'SELECT customer_name FROM reservations WHERE id = $1 AND tenant_id = $2', [reservationId, req.tenantId!]
            );
            if (r.rows.length === 0) {
                reservationId = null;
            } else {
                customerName = r.rows[0]?.customer_name ?? null;
            }
        }
        const inReplyTo = typeof in_reply_to === 'string' && in_reply_to.trim() ? in_reply_to.trim() : null;

        const template = buildCustomEmail({
            customerName: customerName || 'cliente',
            subject: subj,
            body: bod,
        });
        const sendResult = await sendMail(req.tenantId!, {
            to: toEmail,
            subject: template.subject,
            text: template.text,
            html: template.html,
        });
        // in_reply_to is persisted for our own thread reconstruction even if
        // the underlying provider doesn't propagate the RFC header — it's a
        // hint about the composer's intent, not authoritative Message-ID
        // threading data.
        const inserted = await queryWithRetry(
            `INSERT INTO outbound_messages
                (tenant_id, provider, channel, direction, to_email, subject, body, status,
                 message_id, in_reply_to, reservation_id, sent_at)
             VALUES ($7, 'smtp', 'email', 'outbound', $1, $2, $3, 'sent',
                     $4, $5, $6, CURRENT_TIMESTAMP)
             RETURNING id, provider, channel, direction, from_email, to_email,
                       subject, body, status, provider_sid, message_id, in_reply_to,
                       reservation_id, sent_at`,
            [toEmail, subj, bod, sendResult.messageId || null, inReplyTo, reservationId, req.tenantId!]
        );
        const message = inserted.rows[0];

        if (socketService) {
            try { socketService.broadcastToAll(req.tenantId!, 'email:new', { email_key: toEmail.toLowerCase(), message }); }
            catch (err) { console.warn('[email/send] socket broadcast failed:', (err as any)?.message || err); }
        }
        res.json({ ok: true, message });
    } catch (err: any) {
        console.error('POST /email/send error:', err);
        res.status(500).json({ error: err?.message || 'Send failed' });
    }
});

// Send an outbound reply from the inbox composer. Enforces Meta's 24h window
// for WhatsApp freeform (needs an inbound < 24h ago); SMS has no constraint.
// The customer-service window check is deliberately done server-side so the
// UI can render a "window closed" banner without duplicating the rule.
// Allegati in uscita: il file arriva in base64 dal browser, resta a DB e
// viene servito a Twilio da un URL pubblico con token non indovinabile.
// 5 MB e' il limite pratico di WhatsApp per immagini e video; oltre, Meta
// rifiuta comunque.
const OUTBOUND_MEDIA_MAX_BYTES = 5 * 1024 * 1024;
const OUTBOUND_MEDIA_TYPES = /^(image\/(jpeg|png|webp|gif)|video\/(mp4|3gpp)|audio\/(mpeg|ogg|amr|aac)|application\/pdf)$/;

app.post('/messages/attachments', authenticate, requirePermission('reservations:full'), async (req, res) => {
    try {
        const contentType = String(req.body?.content_type || '').toLowerCase().split(';')[0].trim();
        const dataB64 = String(req.body?.data || '');
        const filename = req.body?.filename ? String(req.body.filename).slice(0, 200) : null;
        if (!contentType || !dataB64) {
            return res.status(400).json({ error: 'content_type e data sono obbligatori' });
        }
        if (!OUTBOUND_MEDIA_TYPES.test(contentType)) {
            return res.status(415).json({ error: `Tipo non supportato da WhatsApp: ${contentType}` });
        }
        const buf = Buffer.from(dataB64.replace(/^data:[^,]+,/, ''), 'base64');
        if (buf.length === 0) return res.status(400).json({ error: 'File vuoto' });
        if (buf.length > OUTBOUND_MEDIA_MAX_BYTES) {
            return res.status(413).json({ error: 'File troppo grande: massimo 5 MB' });
        }
        const token = crypto.randomBytes(32).toString('base64url');
        const ins = await queryWithRetry(
            `INSERT INTO outbound_media (tenant_id, token, content_type, filename, bytes, size_bytes, created_by_user_id)
             VALUES ($7, $1, $2, $3, $4, $5, $6) RETURNING id, token, content_type, filename, size_bytes`,
            [token, contentType, filename, buf, buf.length, req.user?.userId ?? null, req.tenantId!]
        );
        res.status(201).json(ins.rows[0]);
    } catch (err: any) {
        console.error('POST /messages/attachments error:', err);
        res.status(500).json({ error: 'Internal server error' });
    }
});

// Pubblico per forza: e' Twilio a scaricare il file, e non ha le nostre
// credenziali. La protezione e' il token da 32 byte nel path — e' anche il
// motivo per cui qui NON c'e' filtro tenant: il token e' unico globale e
// non indovinabile, il tenant e' implicito nella riga trovata.
app.get('/public/media/:token', async (req, res) => {
    try {
        const token = String(req.params.token || '');
        if (!/^[A-Za-z0-9_-]{20,64}$/.test(token)) return res.status(404).send('Not found');
        const r = await queryWithRetry(
            `SELECT content_type, bytes, size_bytes FROM outbound_media WHERE token = $1`,
            [token]
        );
        const row = r.rows[0];
        if (!row) return res.status(404).send('Not found');
        res.setHeader('Content-Type', row.content_type);
        res.setHeader('Content-Length', String(row.size_bytes));
        res.setHeader('Cache-Control', 'public, max-age=3600');
        res.end(row.bytes);
    } catch (err: any) {
        console.error('GET /public/media error:', err);
        res.status(500).send('Internal server error');
    }
});

// Risposta suggerita per una conversazione. Non invia nulla: restituisce il
// testo che il cameriere trova nel campo di scrittura, da leggere e mandare
// (o cestinare). Vedi services/aiReplyService.ts per il perche'.
app.post('/messages/suggest-reply', authenticate, requirePermission('reservations:full'), async (req, res) => {
    try {
        if (!(await getFeatureFlag(req.tenantId!, 'ai_messages_enabled', false))) {
            return res.status(403).json({
                error: 'feature_disabled',
                message: 'Messaggi con AI disattivato. Attivalo da Impostazioni → Messaggi con AI.',
            });
        }
        if (!isAiConfigured()) {
            return res.status(503).json({ error: 'not_configured', message: 'ANTHROPIC_API_KEY non configurata sul backend' });
        }
        const key = String(req.body?.phone_digits ?? '').replace(/\D/g, '').slice(-10);
        if (!key) return res.status(400).json({ error: 'phone_digits mancante' });

        const [msgs, kb] = await Promise.all([
            queryWithRetry(
                `SELECT direction, body, sent_at
                   FROM outbound_messages
                  WHERE tenant_id = $2
                    AND channel IN ('sms','whatsapp')
                    AND (right(to_phone_digits, 10) = $1::text OR right(from_phone_digits, 10) = $1::text)
                  ORDER BY sent_at DESC
                  LIMIT 15`,
                [key, req.tenantId!]
            ),
            queryWithRetry(
                `SELECT title, content FROM ai_knowledge_entries WHERE tenant_id = $1 AND is_active ORDER BY sort_order, id`,
                [req.tenantId!]
            ),
        ]);
        const messages = msgs.rows.reverse();
        if (messages.length === 0) return res.status(404).json({ error: 'Conversazione vuota' });

        // Prenotazione dello stesso numero, la piu' vicina a oggi: e' quella
        // di cui il cliente sta quasi sempre parlando.
        const resv = await queryWithRetry(
            `SELECT r.customer_name, r.reservation_time, r.guests, r.notes, r.reservation_status AS status,
                    ro.name AS room_name
               FROM reservations r
               LEFT JOIN tables t ON t.id = r.table_id AND t.tenant_id = r.tenant_id
               LEFT JOIN rooms ro ON ro.id = t.room_id AND ro.tenant_id = t.tenant_id
              WHERE r.tenant_id = $2
                AND r.phone IS NOT NULL AND r.phone <> ''
                AND ${PHONE_MATCH_KEY_SQL('r.phone')} = ${PHONE_MATCH_KEY_SQL('$1')}
              ORDER BY abs(extract(epoch FROM (r.reservation_time - CURRENT_TIMESTAMP))) ASC
              LIMIT 1`,
            [key, req.tenantId!]
        );

        const suggestion = await generateSuggestedReply({
            messages: messages as any,
            reservation: resv.rows[0] ?? null,
            knowledge: kb.rows as any,
            restaurantName: businessIdentity().name,
        }, {
            // Telemetria consumi Gemini dei "messaggi AI": la stessa tabella
            // che alimenta la pagina Consumi AI (feature 'suggest_reply').
            // Best-effort — un errore qui non deve rompere il suggerimento.
            onUsage: (u) => {
                queryWithRetry(
                    `INSERT INTO ai_token_usage (provider, feature, model, prompt_tokens, output_tokens, total_tokens, user_email, tenant_id)
                     VALUES ('anthropic', 'suggest_reply', $1, $2, $3, $4, $5, $6)`,
                    [u.model, u.promptTokens, u.outputTokens, u.totalTokens || (u.promptTokens + u.outputTokens), (req.user?.email || null), req.tenantId!]
                ).catch(err => console.error('ai_token_usage insert (suggest_reply) failed:', err));
            },
        });

        res.json({
            suggestion,
            // Trasparenza sul perche' non c'e' un suggerimento: senza, sembra
            // che la funzione sia rotta.
            reason: suggestion ? null : 'Serve una verifica umana o l\'informazione non e\' fra le regole',
            knowledge_count: kb.rows.length,
            reservation_linked: resv.rows.length > 0,
        });
    } catch (err: any) {
        if (err instanceof AiReplyError) {
            const status = err.kind === 'not_configured' ? 503 : err.kind === 'no_knowledge' ? 400 : 502;
            return res.status(status).json({ error: err.kind, message: err.message });
        }
        console.error('POST /messages/suggest-reply error:', err);
        res.status(500).json({ error: 'Internal server error' });
    }
});

// --- Agente WhatsApp: propone, non esegue ----------------------------------
// Gli strumenti di sola lettura girano davvero; quelli che scrivono diventano
// una proposta che una persona conferma con un tocco. Vedi
// services/whatsappAgent.ts per il perche' della divisione.

const proposalRow = (r: any) => ({
    id: r.id,
    tool: r.tool,
    args: r.args,
    summary: r.summary,
    suggested_reply: r.suggested_reply,
    status: r.status,
    expires_at: r.expires_at,
    reservation_id: r.reservation_id,
});

app.post('/messages/agent/run', authenticate, requirePermission('reservations:full'), async (req, res) => {
    try {
        if (!(await getFeatureFlag(req.tenantId!, 'ai_messages_enabled', false))) {
            return res.status(403).json({ error: 'feature_disabled', message: 'Messaggi con AI disattivato.' });
        }
        if (!whatsappAgent.isAgentConfigured()) {
            return res.status(503).json({ error: 'not_configured', message: 'ANTHROPIC_API_KEY non configurata sul backend' });
        }
        const key = String(req.body?.phone_digits ?? '').replace(/\D/g, '').slice(-10);
        if (!key) return res.status(400).json({ error: 'phone_digits mancante' });

        const [msgs, kb, soglia] = await Promise.all([
            queryWithRetry(
                `SELECT direction, body, from_phone, to_phone
                   FROM outbound_messages
                  WHERE tenant_id = $2
                    AND channel IN ('sms','whatsapp')
                    AND (right(to_phone_digits, 10) = $1::text OR right(from_phone_digits, 10) = $1::text)
                  ORDER BY sent_at DESC LIMIT 15`, [key, req.tenantId!]),
            queryWithRetry(`SELECT title, content FROM ai_knowledge_entries WHERE tenant_id = $1 AND is_active ORDER BY sort_order, id`, [req.tenantId!]),
            getVoiceLargeGroupThreshold(req.tenantId!),
        ]);
        const messages = msgs.rows.reverse();
        if (messages.length === 0) return res.status(404).json({ error: 'Conversazione vuota' });

        // Stesso scoping della gemella in /messages/suggest-reply: tenant
        // sulla prenotazione e sui JOIN, o l'agente ragionerebbe sulla
        // prenotazione omonima di un altro ristorante.
        const resv = await queryWithRetry(
            `SELECT r.id, r.customer_name, r.reservation_time, r.guests, r.notes,
                    r.reservation_status AS status, ro.name AS room_name
               FROM reservations r
               LEFT JOIN tables t ON t.id = r.table_id AND t.tenant_id = r.tenant_id
               LEFT JOIN rooms ro ON ro.id = t.room_id AND ro.tenant_id = t.tenant_id
              WHERE r.tenant_id = $2
                AND r.phone IS NOT NULL AND r.phone <> ''
                AND ${PHONE_MATCH_KEY_SQL('r.phone')} = ${PHONE_MATCH_KEY_SQL('$1')}
              ORDER BY abs(extract(epoch FROM (r.reservation_time - CURRENT_TIMESTAMP))) ASC
              LIMIT 1`, [key, req.tenantId!]);

        // Numero in formato utile agli strumenti: quello da cui il cliente scrive.
        const inbound = messages.find((m: any) => m.direction === 'inbound');
        const phone = inbound?.from_phone || `+${key}`;

        const result = await whatsappAgent.runAgent({
            tenantId: req.tenantId!,
            phoneDigits: key,
            messages: messages as any,
            reservation: resv.rows[0] ?? null,
            phone,
            knowledge: kb.rows as any,
            largeGroupThreshold: soglia,
            restaurantName: businessIdentity().name,
        });

        let proposta: any = null;
        if (result.proposal) {
            // Una proposta per volta e per conversazione: quelle vecchie
            // decadono, altrimenti lo staff si trova due schede in contrasto.
            await queryWithRetry(
                `UPDATE agent_proposals SET status = 'SUPERSEDED', resolved_at = CURRENT_TIMESTAMP
                  WHERE tenant_id = $2 AND phone_digits = $1 AND status = 'PENDING'`, [key, req.tenantId!]);
            const ins = await queryWithRetry(
                `INSERT INTO agent_proposals (tenant_id, phone_digits, tool, args, summary, suggested_reply, reservation_id)
                 VALUES ($7, $1, $2, $3::jsonb, $4, $5, $6) RETURNING *`,
                [key, result.proposal.tool, JSON.stringify(result.proposal.args),
                 result.proposal.summary, result.reply, resv.rows[0]?.id ?? null, req.tenantId!]);
            proposta = proposalRow(ins.rows[0]);
        }

        res.json({
            reply: result.reply,
            proposal: proposta,
            checks: result.checks,
            reason: result.reason ?? null,
            knowledge_count: kb.rows.length,
        });
    } catch (err: any) {
        if (err instanceof whatsappAgent.AgentError) {
            const status = err.kind === 'not_configured' ? 503 : err.kind === 'no_knowledge' ? 400 : 502;
            return res.status(status).json({ error: err.kind, message: err.message });
        }
        console.error('POST /messages/agent/run error:', err);
        res.status(500).json({ error: 'Internal server error' });
    }
});

// Esegue la proposta: e' QUI che si scrive sulle prenotazioni, e solo dopo un
// tocco di una persona. Usa gli stessi strumenti di Sofia col canale WhatsApp.
app.post('/messages/agent/proposals/:id/confirm', authenticate, requirePermission('reservations:full'), async (req, res) => {
    try {
        const id = parseInt(req.params.id, 10);
        if (!Number.isFinite(id)) return res.status(400).json({ error: 'id non valido' });

        // Lock di riga: due tocchi ravvicinati non devono eseguire due volte.
        const client = await pool.connect();
        try {
            await client.query('BEGIN');
            const r = await client.query(`SELECT * FROM agent_proposals WHERE id = $1 AND tenant_id = $2 FOR UPDATE`, [id, req.tenantId!]);
            const prop = r.rows[0];
            if (!prop) { await client.query('ROLLBACK'); return res.status(404).json({ error: 'Proposta non trovata' }); }
            if (prop.status !== 'PENDING') {
                await client.query('ROLLBACK');
                return res.status(409).json({ error: 'already_resolved', status: prop.status });
            }
            if (new Date(prop.expires_at).getTime() < Date.now()) {
                await client.query(`UPDATE agent_proposals SET status='EXPIRED', resolved_at=CURRENT_TIMESTAMP WHERE id=$1`, [id]);
                await client.query('COMMIT');
                return res.status(409).json({
                    error: 'expired',
                    message: 'Proposta scaduta: la situazione della sala potrebbe essere cambiata. Rilancia il suggerimento.',
                });
            }
            await client.query(`UPDATE agent_proposals SET status='EXECUTING' WHERE id=$1`, [id]);
            await client.query('COMMIT');
        } finally {
            client.release();
        }

        const prop = (await queryWithRetry(`SELECT * FROM agent_proposals WHERE id=$1 AND tenant_id=$2`, [id, req.tenantId!])).rows[0];
        const args = prop.args || {};
        const esegui = prop.tool === 'create_reservation' ? bookingTools.createReservation
            : prop.tool === 'modify_reservation' ? bookingTools.modifyReservation
            : prop.tool === 'cancel_reservation' ? bookingTools.cancelReservation
            : null;
        if (!esegui) {
            await queryWithRetry(`UPDATE agent_proposals SET status='FAILED', resolved_at=CURRENT_TIMESTAMP WHERE id=$1`, [id]);
            return res.status(400).json({ error: 'Strumento non eseguibile', tool: prop.tool });
        }

        const outcome = await esegui(req.tenantId!, args, WHATSAPP_CHANNEL);
        const riuscito = outcome.body?.success === true;
        await queryWithRetry(
            `UPDATE agent_proposals
                SET status = $2, result = $3::jsonb, resolved_at = CURRENT_TIMESTAMP, resolved_by_user_id = $4
              WHERE id = $1`,
            [id, riuscito ? 'DONE' : 'FAILED', JSON.stringify(outcome.body), req.user?.userId ?? null]);

        res.status(outcome.serverError ? 500 : 200).json({ ok: riuscito, tool: prop.tool, result: outcome.body });
    } catch (err: any) {
        console.error('POST /messages/agent/proposals/:id/confirm error:', err);
        res.status(500).json({ error: 'Internal server error' });
    }
});

app.post('/messages/agent/proposals/:id/discard', authenticate, requirePermission('reservations:full'), async (req, res) => {
    try {
        const id = parseInt(req.params.id, 10);
        if (!Number.isFinite(id)) return res.status(400).json({ error: 'id non valido' });
        const r = await queryWithRetry(
            `UPDATE agent_proposals SET status='DISCARDED', resolved_at=CURRENT_TIMESTAMP, resolved_by_user_id=$2
              WHERE id=$1 AND tenant_id=$3 AND status='PENDING' RETURNING id`, [id, req.user?.userId ?? null, req.tenantId!]);
        if (r.rows.length === 0) return res.status(409).json({ error: 'Proposta non più in attesa' });
        res.json({ ok: true });
    } catch (err: any) {
        console.error('POST /messages/agent/proposals/:id/discard error:', err);
        res.status(500).json({ error: 'Internal server error' });
    }
});

app.post('/messages/send', authenticate, requireFeature('whatsapp'), requirePermission('reservations:full'), async (req, res) => {
    try {
        const { phone, text, channel } = req.body || {};
        // Gli allegati sono referenziati per token: il file e' gia' a DB
        // (POST /messages/attachments) e qui diventa l'URL che Twilio scarica.
        const attachmentTokens: string[] = Array.isArray(req.body?.attachment_tokens)
            ? req.body.attachment_tokens.map((t: any) => String(t)).filter(Boolean).slice(0, 10)
            : [];
        const hasText = typeof text === 'string' && text.trim().length > 0;
        if (!phone || (!hasText && attachmentTokens.length === 0)) {
            return res.status(400).json({ error: 'Servono un telefono e almeno un testo o un allegato' });
        }
        const desiredChannel: 'whatsapp' | 'sms' = channel === 'sms' ? 'sms' : 'whatsapp';
        const key = String(phone).replace(/\D/g, '').slice(-10);
        if (!key) return res.status(400).json({ error: 'invalid phone' });

        if (desiredChannel === 'whatsapp') {
            const win = await queryWithRetry(
                `SELECT MAX(sent_at) AS last_inbound_at
                 FROM outbound_messages
                 WHERE tenant_id = $2
                   AND direction = 'inbound' AND channel = 'whatsapp'
                   AND right(from_phone_digits, 10) = $1::text`,
                [key, req.tenantId!]
            );
            const lastInbound = win.rows[0]?.last_inbound_at as Date | null;
            const withinWindow = !!lastInbound
                && (Date.now() - new Date(lastInbound).getTime()) < 24 * 3600 * 1000;
            if (!withinWindow) {
                return res.status(409).json({
                    error: 'window_closed',
                    message: 'Fuori dalla finestra 24h WhatsApp: serve un template approvato.',
                });
            }
        }

        let mediaUrls: string[] = [];
        if (attachmentTokens.length > 0) {
            if (desiredChannel !== 'whatsapp') {
                return res.status(400).json({ error: 'Gli allegati si inviano solo via WhatsApp' });
            }
            const found = await queryWithRetry(
                `SELECT token FROM outbound_media WHERE token = ANY($1) AND tenant_id = $2`,
                [attachmentTokens, req.tenantId!]
            );
            const known = new Set(found.rows.map((r: any) => r.token));
            const missing = attachmentTokens.filter(t => !known.has(t));
            if (missing.length > 0) return res.status(400).json({ error: 'Allegato non trovato' });
            // ATTENZIONE: qui serve il dominio del BACKEND, non quello della
            // SPA. publicBaseUrl() punta a crm.vecchiofrantoio.com (Vercel),
            // che su un path sconosciuto risponde 200 con l'index.html: Twilio
            // scaricava una pagina HTML al posto del file e falliva con 63019
            // "Media failed to download", senza che nulla arrivasse al cliente.
            const base = backendBaseUrl();
            if (!base) {
                return res.status(503).json({ error: 'Allegati non inviabili: manca PUBLIC_WEBHOOK_BASE_URL sul backend' });
            }
            if (/localhost|127\.0\.0\.1/.test(base)) {
                return res.status(503).json({ error: 'Allegati non inviabili da ambiente locale: Twilio non raggiunge questo host' });
            }
            mediaUrls = attachmentTokens.map(t => `${base}/public/media/${t}`);
        }

        const body = hasText ? text.trim() : '';
        const result = desiredChannel === 'whatsapp'
            ? await sendWhatsAppText(req.tenantId!, phone, body, null, undefined, mediaUrls)
            : await sendTwilioSms(req.tenantId!, phone, body);

        let row: any = null;
        if (result.sid) {
            const r = await queryWithRetry(
                `SELECT * FROM outbound_messages WHERE provider_sid = $1 AND tenant_id = $2 LIMIT 1`,
                [result.sid, req.tenantId!]
            );
            row = r.rows[0] ?? null;
        }
        // La bolla in uscita deve mostrare quello che e' partito: gli allegati
        // finiscono sulla riga come per gli inbound, con l'URL pubblico.
        if (row && mediaUrls.length > 0) {
            const media = attachmentTokens.map((t, i) => ({ url: mediaUrls[i], token: t }));
            const enriched = await queryWithRetry(
                `UPDATE outbound_messages SET media = $2::jsonb WHERE id = $1 AND tenant_id = $3 RETURNING *`,
                [row.id, JSON.stringify(media), req.tenantId!]
            );
            row = enriched.rows[0] ?? row;
            await queryWithRetry(
                `UPDATE outbound_media SET message_id = $1 WHERE token = ANY($2) AND tenant_id = $3`,
                [row.id, attachmentTokens, req.tenantId!]
            ).catch(() => {});
        }
        if (row && socketService) {
            socketService.broadcastToAll(req.tenantId!, 'message:outbound', row);
        }
        res.json({ ok: true, message: row, channel: result.channel, sid: result.sid ?? null });
    } catch (err: any) {
        console.error('POST /messages/send error:', err);
        res.status(500).json({ error: err?.message || 'Internal server error' });
    }
});


// ============================================
// PAYMENT LINK REQUESTS (Revolut hosted checkout)
// ============================================

// Format an amount in minor units as an Italian euro string ("€ 15,00").
function formatEuroMinor(cents: number): string {
    return `€ ${(cents / 100).toFixed(2).replace('.', ',')}`;
}

// Base URL where the SPA is served (the pay-at-table page lives at
// {base}/pay/{token}). Read from CRM_APP_BASE_URL first so it can be
// pointed at a preview/dev deploy; falls back to the production domain
// so the flow works out of the box. Defined in paymentProviderService
// because the gateway modules build redirect/callback URLs from it too.
function payAtTableBaseUrl(): string {
    return publicBaseUrl();
}

// Message sent to the guest when the waiter forwards the pay-at-table
// link from the reservation modal. Free-form (SMS or WhatsApp inside the
// 24h window) because we don't have a Meta-approved template for this
// flow yet — keep it short so a single SMS segment covers it.
function buildTableBillLinkMessage(customerName: string, amountCents: number, covers: number, url: string): string {
    const amount = formatEuroMinor(amountCents);
    const coversLabel = covers === 1 ? '1 coperto' : `${covers} coperti`;
    return `Ciao ${toTitleCase(customerName)}, ecco il link per pagare al tavolo (${coversLabel} · totale ${amount}): ${url}\nGrazie!`;
}

// Compose the message we send to the customer with the Revolut checkout link.
// Kept intentionally short so it fits comfortably inside an SMS segment when
// WhatsApp isn't available.
function buildPaymentMessage(customerName: string, amountCents: number, url: string, description?: string | null): string {
    const amount = formatEuroMinor(amountCents);
    const desc = (description || '').trim();
    const intro = `Ciao ${toTitleCase(customerName)}, per completare la prenotazione presso ${businessIdentity().name} serve un anticipo di ${amount}.`;
    const line = desc ? `${intro}\n${desc}` : intro;
    return `${line}\nPuoi pagare in sicurezza qui: ${url}\n\nGrazie!`;
}

// Shared auto-deposit policy (Settings → Integrazioni): true when the policy
// is enabled, the party is at/above the guest threshold, and a payment
// provider is actually configured. Used by both self-service channels (web
// booking + voice agent) so they can't drift on when a caparra is due.
const DEPOSIT_DEFAULTS = { minGuests: 9, perPersonCents: 1000 };

// Politica caparra in un posto solo: soglia e importo servono anche alla
// pagina pubblica e ai messaggi, non solo alla decisione "serve o no".
async function getAutoDepositPolicy(tenantId: number): Promise<{ enabled: boolean; minGuests: number; perPersonCents: number }> {
    try {
        const cfgRow = await queryWithRetry(
            `SELECT auto_deposit_enabled, auto_deposit_min_guests, auto_deposit_per_person_cents
               FROM integration_settings WHERE tenant_id = $1 AND provider = 'revolut'`,
            [tenantId]
        );
        const r = cfgRow.rows[0];
        const n = Number(r?.auto_deposit_min_guests);
        const c = Number(r?.auto_deposit_per_person_cents);
        return {
            enabled: Boolean(r?.auto_deposit_enabled),
            minGuests: Number.isInteger(n) && n >= 1 ? n : DEPOSIT_DEFAULTS.minGuests,
            perPersonCents: Number.isInteger(c) && c > 0 ? c : DEPOSIT_DEFAULTS.perPersonCents,
        };
    } catch (err) {
        console.warn('[auto-deposit] policy lookup failed:', (err as any)?.message || err);
        return { enabled: false, ...DEPOSIT_DEFAULTS };
    }
}

async function isAutoDepositRequired(tenantId: number, guests: number): Promise<boolean> {
    const policy = await getAutoDepositPolicy(tenantId);
    if (!policy.enabled || guests < policy.minGuests) return false;
    try {
        return await isPaymentConfiguredForFlow(tenantId, 'deposit');
    } catch (err) {
        console.warn('[auto-deposit] provider check failed:', (err as any)?.message || err);
        return false;
    }
}

// Pagina pubblica con le condizioni della caparra (sezione ancorata del
// modulo di prenotazione): un solo posto da aggiornare quando cambiano, e i
// messaggi si limitano a linkarla.
const DEPOSIT_TERMS_URL = `${(process.env.PUBLIC_BOOKING_BASE_URL || 'https://prenotazioni.vecchiofrantoio.com').replace(/\/$/, '')}/prenota#caparra`;

// Ack sent to the customer when a public web booking with >8 guests triggers
// an automatic deposit request (€10/person). Combines the "richiesta ricevuta"
// wording with the Revolut checkout link so the guest knows exactly what to
// do next.
function buildDepositRequestMessage(
    customerName: string,
    guestsLabel: string,
    dateLabel: string,
    time: string,
    amountCents: number,
    checkoutUrl: string,
    perPersonCents: number = DEPOSIT_DEFAULTS.perPersonCents
): string {
    const amount = formatEuroMinor(amountCents);
    const perPerson = formatEuroMinor(perPersonCents);
    // Niente link alle condizioni qui: l'SMS resta su due segmenti e il
    // cliente le trova sulla pagina di prenotazione (l'email invece lo porta,
    // dove non costa nulla).
    return `Ciao ${toTitleCase(customerName)}, per confermare la prenotazione per ${guestsLabel} il ${dateLabel} alle ${time} serve una caparra di ${amount} (${perPerson} a persona).\nPaga in sicurezza qui: ${checkoutUrl}\n\nAppena riceviamo il pagamento ti confermeremo il tavolo. Grazie!`;
}

// Message sent to the customer as soon as the Revolut ORDER_COMPLETED webhook
// arrives on a reservation-linked payment. Confirms both the deposit receipt
// and the reservation itself (which we auto-flip to CONFIRMED at the same time).
function buildDepositConfirmationMessage(
    customerName: string | null | undefined,
    reservationTime: string | Date,
    guests: number | null | undefined,
    amountCents: number,
    roomName?: string | null
): string {
    const { dateLabel, timeLabel } = formatBookingDateTime(asUtcInstant(reservationTime));
    const fullName = toTitleCase(customerName);
    const greeting = fullName ? `Ciao ${fullName}` : 'Ciao';
    const guestsNum = Math.max(1, Math.trunc(Number(guests) || 1));
    const persone = guestsNum === 1 ? 'persona' : 'persone';
    const room = (roomName ?? '').trim();
    const roomPart = room ? ` in ${room}` : '';
    const amount = formatEuroMinor(amountCents);
    return `${greeting}, abbiamo ricevuto la caparra di ${amount}. La tua prenotazione per ${guestsNum} ${persone} il ${dateLabel} alle ${timeLabel}${roomPart} e' confermata. A presto!`;
}

// Sent to the guest when staff refund a deposit from the Pagamenti page.
//
// Deliberately says nothing about the booking itself: refunding a deposit and
// cancelling a table are separate decisions here (the reservation keeps its
// status), so promising either "confermata" or "annullata" would be a guess.
// It states the fact, sets the expectation that the money takes a few days to
// land — the question staff would otherwise get by phone — and invites a reply.
//
// Accented characters are avoided on purpose, as in every other customer
// message: they'd force UCS-2 encoding and halve the SMS length budget.
function buildRefundNotificationMessage(
    customerName: string | null | undefined,
    amountCents: number,
    reservationTime?: string | Date | null
): string {
    const fullName = toTitleCase(customerName);
    const greeting = fullName ? `Ciao ${fullName}` : 'Ciao';
    const amount = formatEuroMinor(amountCents);
    let when = '';
    if (reservationTime) {
        const { dateLabel, timeLabel } = formatBookingDateTime(asUtcInstant(reservationTime));
        when = ` della prenotazione del ${dateLabel} alle ${timeLabel}`;
    }
    return `${greeting}, ti abbiamo rimborsato la caparra di ${amount}${when}. `
        + `L'accredito puo' richiedere qualche giorno lavorativo, secondo la tua banca. `
        + `Per qualsiasi dubbio rispondi a questo messaggio. Grazie!`;
}

// Global list of payment requests across all reservations, powering the
// dedicated /pagamenti page. Supports the same filter vocabulary as the
// UI: free-text search on customer/description/order id, status filter
// (comma-separated), and a date range on created_at.
app.get('/payments', authenticate, requirePermission('payments:view'), async (req, res) => {
    try {
        const { from, to, q, status } = req.query as Record<string, string | undefined>;
        const limit = Math.min(Math.max(parseInt(String(req.query.limit ?? '100'), 10) || 100, 1), 200);
        const offset = Math.max(parseInt(String(req.query.offset ?? '0'), 10) || 0, 0);

        // Il tenant è la prima condizione, sempre presente: la lista dei
        // pagamenti è per ristorante, i filtri si sommano dopo.
        const where: string[] = ['pr.tenant_id = $1'];
        const params: any[] = [req.tenantId!];

        if (from && /^\d{4}-\d{2}-\d{2}$/.test(from)) {
            params.push(from);
            where.push(`pr.created_at >= $${params.length}::date`);
        }
        if (to && /^\d{4}-\d{2}-\d{2}$/.test(to)) {
            params.push(to);
            where.push(`pr.created_at < ($${params.length}::date + INTERVAL '1 day')`);
        }
        if (q && q.trim()) {
            params.push(`%${q.trim()}%`);
            const idx = params.length;
            where.push(
                `(r.customer_name ILIKE $${idx}
                  OR r.phone ILIKE $${idx}
                  OR pr.description ILIKE $${idx}
                  OR pr.provider_order_id ILIKE $${idx})`
            );
        }
        if (status && status.trim()) {
            // Comma-separated, case-insensitive; we store uppercase status
            // so we upper() both sides.
            const values = status.split(',').map(s => s.trim().toUpperCase()).filter(Boolean);
            if (values.length > 0) {
                const placeholders = values.map(v => {
                    params.push(v);
                    return `$${params.length}`;
                }).join(',');
                where.push(`upper(pr.status) IN (${placeholders})`);
            }
        }

        const whereSql = where.length ? `WHERE ${where.join(' AND ')}` : '';

        params.push(limit);
        params.push(offset);

        const result = await queryWithRetry(
            `SELECT pr.id, pr.reservation_id, pr.amount_cents, pr.currency, pr.description,
                    pr.status, pr.provider, pr.provider_order_id, pr.checkout_url,
                    pr.delivery_channel, pr.delivery_provider_sid, pr.delivery_error,
                    pr.created_at, pr.updated_at, pr.completed_at,
                    r.customer_name AS reservation_customer_name,
                    r.phone AS reservation_phone,
                    r.reservation_time AS reservation_time,
                    r.guests AS reservation_guests,
                    r.reservation_status AS reservation_status,
                    pr.table_bill_split_id AS table_bill_split_id,
                    tbs.table_bill_id AS table_bill_id,
                    tbs.claimant_label AS claimant_label,
                    tb.total_cents AS bill_total_cents,
                    tb.status AS bill_status,
                    t.name AS table_name
             FROM payment_requests pr
             LEFT JOIN reservations r ON r.id = pr.reservation_id AND r.tenant_id = pr.tenant_id
             LEFT JOIN table_bill_splits tbs ON tbs.id = pr.table_bill_split_id
             LEFT JOIN table_bills tb ON tb.id = tbs.table_bill_id
             LEFT JOIN tables t ON t.id = tb.table_id AND t.tenant_id = tb.tenant_id
             ${whereSql}
             ORDER BY pr.created_at DESC
             LIMIT $${params.length - 1} OFFSET $${params.length}`,
            params
        );

        const countResult = await queryWithRetry(
            `SELECT COUNT(*)::int AS total
             FROM payment_requests pr
             LEFT JOIN reservations r ON r.id = pr.reservation_id AND r.tenant_id = pr.tenant_id
             ${whereSql}`,
            params.slice(0, params.length - 2)
        );

        res.json({
            items: result.rows,
            total: countResult.rows[0]?.total ?? 0,
            limit,
            offset,
        });
    } catch (err: any) {
        console.error('GET /payments error:', err);
        res.status(500).json({ error: 'Internal server error', detail: err?.message });
    }
});

// Badge sidebar "Pagamenti": conta gli incassi (COMPLETED/PAID) non ancora
// visti. La colonna seen_at viene marcata da /payments/mark-seen quando
// l'operatore apre la pagina — così il conteggio è condiviso tra dispositivi
// (a differenza di un last-seen in localStorage).
app.get('/payments/unseen-count', authenticate, requirePermission('payments:view'), async (req, res) => {
    try {
        const result = await queryWithRetry(
            `SELECT COUNT(*)::int AS count
             FROM payment_requests
             WHERE tenant_id = $1 AND upper(status) IN ('COMPLETED','PAID') AND seen_at IS NULL`,
            [req.tenantId!]
        );
        res.json({ count: result.rows[0]?.count ?? 0 });
    } catch (err: any) {
        console.error('GET /payments/unseen-count error:', err);
        res.status(500).json({ error: 'Internal server error' });
    }
});

// Marca visti SOLO i pagati: un PENDING che si completa più tardi deve poter
// tornare a far salire il badge.
app.post('/payments/mark-seen', authenticate, requirePermission('payments:view'), async (req, res) => {
    try {
        const result = await queryWithRetry(
            `UPDATE payment_requests SET seen_at = NOW()
             WHERE tenant_id = $1 AND upper(status) IN ('COMPLETED','PAID') AND seen_at IS NULL
             RETURNING id`,
            [req.tenantId!]
        );
        if (result.rows.length > 0) {
            const socketId = req.headers['x-socket-id'] as string;
            if (socketService) socketService.broadcastToAll(req.tenantId!, 'payments:seen', { count: result.rows.length }, socketId);
        }
        res.json({ marked: result.rows.length });
    } catch (err: any) {
        console.error('POST /payments/mark-seen error:', err);
        res.status(500).json({ error: 'Internal server error' });
    }
});

// Messages associated with a payment. Since payments don't have their own
// FK on outbound_messages we surface the whole reservation timeline — the
// UI can spot the ones that actually relate to the payment (they contain
// the checkout URL). Same shape as GET /reservations/:id/messages.
app.get('/payments/:id/messages', authenticate, requirePermission('payments:view'), async (req, res) => {
    try {
        const id = parseInt(req.params.id, 10);
        if (!Number.isFinite(id)) return res.status(400).json({ error: 'Invalid id' });

        const payRow = await queryWithRetry(
            `SELECT pr.reservation_id, pr.checkout_url, r.phone, r.email
             FROM payment_requests pr
             LEFT JOIN reservations r ON r.id = pr.reservation_id AND r.tenant_id = pr.tenant_id
             WHERE pr.id = $1 AND pr.tenant_id = $2`,
            [id, req.tenantId!]
        );
        if (payRow.rows.length === 0) return res.status(404).json({ error: 'Not found' });
        const row = payRow.rows[0];
        const reservationId: number | null = row.reservation_id;
        const phone: string | null = row.phone;
        const email: string | null = row.email;
        const checkoutUrl: string | null = row.checkout_url;

        const digits = phone ? String(phone).replace(/\D/g, '') : '';
        const suffix = digits.length >= 8 ? digits.slice(-10) : null;

        const conditions: string[] = [];
        const params: any[] = [];
        if (reservationId != null) {
            params.push(reservationId);
            conditions.push(`reservation_id = $${params.length}`);
        }
        if (suffix) {
            params.push(suffix);
            conditions.push(`right(to_phone_digits, 10) = $${params.length}`);
        }
        if (email) {
            params.push(email);
            conditions.push(`lower(to_email) = lower($${params.length})`);
        }
        if (conditions.length === 0) return res.json({ items: [], checkout_url: checkoutUrl });

        params.push(req.tenantId!);
        const result = await queryWithRetry(
            `SELECT id, provider, channel, to_phone, to_email, subject, body, status, provider_sid,
                    reservation_id, sent_at, delivered_at, failed_at,
                    error_code, error_message
             FROM outbound_messages
             WHERE tenant_id = $${params.length}
               AND (${conditions.join(' OR ')})
             ORDER BY sent_at DESC
             LIMIT 100`,
            params
        );
        // Attach `is_payment_link` so the client can highlight rows that
        // actually contain this payment's checkout URL — the reservation
        // timeline may also carry booking confirmations, reminders, etc.
        const items = result.rows.map((m: any) => ({
            ...m,
            is_payment_link: !!(checkoutUrl && m.body && String(m.body).includes(checkoutUrl)),
        }));
        res.json({ items, checkout_url: checkoutUrl });
    } catch (err: any) {
        console.error('GET /payments/:id/messages error:', err);
        res.status(500).json({ error: 'Internal server error', detail: err?.message });
    }
});

// List all payment requests attached to a reservation. Powers the small
// history list rendered inside the reservation modal.
app.get('/payments/requests', authenticate, requirePermission('reservations:view'), async (req, res) => {
    try {
        const reservationId = req.query.reservation_id ? parseInt(String(req.query.reservation_id), 10) : NaN;
        if (!Number.isFinite(reservationId)) {
            return res.status(400).json({ error: 'reservation_id is required' });
        }
        const result = await queryWithRetry(
            `SELECT id, reservation_id, amount_cents, currency, description, status, provider,
                    provider_order_id, checkout_url, delivery_channel, delivery_provider_sid,
                    delivery_error, created_by_user_id, created_at, updated_at, completed_at, metadata
             FROM payment_requests
             WHERE reservation_id = $1 AND tenant_id = $2
             ORDER BY created_at DESC`,
            [reservationId, req.tenantId!]
        );
        res.json(result.rows);
    } catch (err: any) {
        console.error('GET /payments/requests error:', err);
        res.status(500).json({ error: 'Internal server error', detail: err?.message });
    }
});

// Create a payment link for a reservation. Body: { reservation_id, amount, description?, channel? }
// where `amount` is in euros (accepts decimal) and `channel` is one of
// 'email' | 'whatsapp' | 'sms' | 'auto' (default 'auto'). The operator picks
// the channel in the "Richiedi un acconto" section; 'auto' keeps the historical
// behaviour (WhatsApp template first, SMS fallback) for any caller that omits it.
app.post('/payments/requests', authenticate, requirePermission('reservations:full'), async (req, res) => {
    try {
        if (!(await isPaymentConfiguredForFlow(req.tenantId!, 'deposit'))) {
            const effective = await getPaymentProviderForFlow(req.tenantId!, 'deposit');
            return res.status(503).json({ error: `${providerLabel(effective)} non è configurato (credenziali mancanti)` });
        }

        const { reservation_id, amount, description } = req.body ?? {};
        const reservationId = parseInt(String(reservation_id), 10);
        const amountEur = Number(amount);
        if (!Number.isFinite(reservationId)) return res.status(400).json({ error: 'reservation_id is required' });
        if (!Number.isFinite(amountEur) || amountEur <= 0) return res.status(400).json({ error: 'amount must be > 0' });

        const amountCents = Math.round(amountEur * 100);
        if (amountCents < 50) return res.status(400).json({ error: 'importo minimo € 0,50' });

        const rawChannel = String(req.body?.channel ?? '').toLowerCase();
        const channel: 'email' | 'whatsapp' | 'sms' | 'auto' =
            rawChannel === 'email' || rawChannel === 'whatsapp' || rawChannel === 'sms' ? rawChannel : 'auto';

        // Fetch the reservation so we can pre-fill the message and check that the
        // chosen channel has somewhere to land (email address or phone number).
        const resvResult = await queryWithRetry(
            // Guardia FK: un reservation_id di un altro tenant cade nel 404
            // prima di creare una richiesta di pagamento agganciata altrove.
            'SELECT id, customer_name, phone, email, reservation_time, guests FROM reservations WHERE id = $1 AND tenant_id = $2',
            [reservationId, req.tenantId!]
        );
        if (resvResult.rowCount === 0) return res.status(404).json({ error: 'Prenotazione non trovata' });
        const reservation = resvResult.rows[0];

        // Per-channel gate: contact detail present, and (email) SMTP configured.
        // WhatsApp/auto route through sendBookingConfirmation, which itself falls
        // back to SMS when WhatsApp isn't configured — so no hard gate there.
        if (channel === 'email') {
            if (!reservation.email) return res.status(400).json({ error: 'La prenotazione non ha un indirizzo email' });
            if (!(await isSmtpConfigured(req.tenantId!))) return res.status(400).json({ error: 'Email non configurata (server SMTP mancante)' });
        } else {
            if (!reservation.phone) return res.status(400).json({ error: 'La prenotazione non ha un numero di telefono' });
            if (channel === 'sms' && !isTwilioSmsConfigured()) return res.status(400).json({ error: 'SMS non configurato' });
        }

        // Create the gateway order first — if the API call fails we don't
        // want to persist a half-baked row. The `reference` is how the
        // webhook will correlate the event back to our reservation.
        const orderDescription = (typeof description === 'string' && description.trim())
            ? description.trim()
            : `Prenotazione #${reservation.id} - ${reservation.guests} persone`;
        const order = await createPaymentOrder(req.tenantId!, {
            amount: amountCents,
            currency: 'EUR',
            description: orderDescription,
            reference: `reservation:${reservation.id}`,
            flow: 'deposit',
        });

        const inserted = await queryWithRetry(
            `INSERT INTO payment_requests
                (tenant_id, reservation_id, amount_cents, currency, description, status, provider,
                 provider_order_id, checkout_url, created_by_user_id, metadata)
             VALUES ($10, $1, $2, 'EUR', $3, $4, $5, $6, $7, $8, $9)
             RETURNING *`,
            [
                reservation.id,
                amountCents,
                orderDescription,
                order.status,
                order.provider,
                order.id,
                order.checkoutUrl,
                req.user?.userId ?? null,
                JSON.stringify(order.metadata),
                req.tenantId!,
            ]
        );
        const paymentRequest = inserted.rows[0];

        // Fire-and-forget delivery on the chosen channel. Failures update
        // delivery_error but don't fail the API call — the operator can still
        // copy the link from the UI. Routing:
        //   email          → payment-link email (no phone fallback possible)
        //   sms            → SMS only (explicit choice, no WA)
        //   whatsapp/auto  → WhatsApp template, SMS fallback on WA failure
        //                    (sendBookingConfirmation's existing behaviour)
        const resvInstant = new Date(reservation.reservation_time);
        const depositDateLabel = resvInstant.toLocaleDateString('it-IT', { timeZone: 'Europe/Rome', day: '2-digit', month: '2-digit', year: 'numeric' });
        const depositTimeLabel = resvInstant.toLocaleTimeString('it-IT', { timeZone: 'Europe/Rome', hour: '2-digit', minute: '2-digit', hour12: false });
        const depositGuestsLabel = `${reservation.guests} ${Number(reservation.guests) === 1 ? 'persona' : 'persone'}`;
        const whatsappTemplate = buildBookingDepositRequestTemplate(
            reservation.customer_name,
            depositGuestsLabel,
            depositDateLabel,
            depositTimeLabel,
            amountCents,
            order.checkoutUrl
        );
        const message = buildPaymentMessage(reservation.customer_name, amountCents, order.checkoutUrl, orderDescription);

        const deliver = async (): Promise<{ channel: string | null; sid: string | null }> => {
            if (channel === 'email') {
                const { subject, text, html } = buildDepositRequestEmail({
                    customerName: reservation.customer_name,
                    amountCents,
                    checkoutUrl: order.checkoutUrl,
                    description: orderDescription,
                });
                const emailStatus = await getSmtpConfigStatus(req.tenantId!).catch(() => null);
                const emailProvider: 'smtp' | 'resend' = emailStatus?.provider === 'resend' ? 'resend' : 'smtp';
                try {
                    const sent = await sendMail(req.tenantId!, { to: String(reservation.email), subject, text, html });
                    await logOutboundEmail({ tenantId: req.tenantId!, provider: emailProvider, to: String(reservation.email), subject, body: text, messageId: sent.messageId || null, reservationId: reservation.id });
                    return { channel: 'email', sid: sent.messageId || null };
                } catch (sendErr: any) {
                    await logOutboundEmail({ tenantId: req.tenantId!, provider: emailProvider, to: String(reservation.email), subject, body: text, reservationId: reservation.id, errorMessage: sendErr?.message || String(sendErr) });
                    throw sendErr;
                }
            }
            if (channel === 'sms') {
                const r = await sendTwilioSms(req.tenantId!, reservation.phone, message, reservation.id);
                return { channel: r.channel, sid: r.sid ?? null };
            }
            const r = await sendBookingConfirmation(req.tenantId!, reservation.phone, message, reservation.id, { whatsappTemplate });
            return { channel: r.channel, sid: r.sid ?? null };
        };

        deliver().then(async (delivery) => {
            try {
                await queryWithRetry(
                    `UPDATE payment_requests
                     SET delivery_channel = $1, delivery_provider_sid = $2, delivery_error = NULL, updated_at = CURRENT_TIMESTAMP
                     WHERE id = $3`,
                    [delivery.channel || null, delivery.sid || null, paymentRequest.id]
                );
            } catch (err) {
                console.warn('[payments] delivery persist failed:', (err as any)?.message || err);
            }
        }).catch(async (err) => {
            console.error('[payments] delivery send failed:', err?.message || err);
            try {
                await queryWithRetry(
                    `UPDATE payment_requests
                     SET delivery_error = $1, updated_at = CURRENT_TIMESTAMP
                     WHERE id = $2`,
                    [String(err?.message || err).slice(0, 500), paymentRequest.id]
                );
            } catch { /* ignore */ }
        });

        if (req.user) {
            LogService.logActivity(
                req.tenantId!,
                req.user.userId,
                req.user.email,
                req.user.email,
                ActivityAction.CREATE,
                ResourceType.RESERVATION,
                reservation.id,
                `${reservation.customer_name} — richiesta pagamento ${formatEuroMinor(amountCents)}`
            );
        }

        try { socketService?.broadcastToAll(req.tenantId!, 'paymentRequest:created', paymentRequest); }
        catch (err) { console.warn('[payments] socket broadcast failed:', (err as any)?.message || err); }

        // The booking card's payment badge reads latest_payment_* off the
        // reservation row: without this nudge the icon only appeared after a
        // full page reload.
        broadcastReservationsUpdatedByIds([reservation.id]).catch(() => {});

        res.status(201).json(paymentRequest);
    } catch (err: any) {
        console.error('POST /payments/requests error:', err);
        res.status(500).json({ error: 'Internal server error', detail: err?.message });
    }
});

// Propagate a payment order transition down to the table_bill_splits row
// (and, on full payment, to the parent bill). Idempotent: the CLAIMED
// guard on UPDATE means replaying an already-PAID split is a no-op.
// Kept separate from applyPaymentOrderTransition so the split logic can
// evolve without touching the deposit flow.
async function applyBillSplitTransition(
    // tenantId: quello della payment_request che ha innescato la transizione
    // (webhook/riconciliatore, nessun JWT in mano).
    tenantId: number,
    splitId: number,
    event: string,
    isFirstCompletion: boolean,
): Promise<void> {
    // First: find the parent bill_id so we can broadcast and, on
    // completion, promote the bill to SETTLED under a single query.
    const splitRs = await queryWithRetry(
        `SELECT table_bill_id, amount_cents, status FROM table_bill_splits WHERE id = $1 AND tenant_id = $2`,
        [splitId, tenantId]
    );
    if (splitRs.rowCount === 0) {
        console.warn('[bill-split] transition: split not found', splitId);
        return;
    }
    const { table_bill_id: billId, amount_cents: amount } = splitRs.rows[0];

    if (event === 'ORDER_COMPLETED') {
        if (!isFirstCompletion) return;

        let upd = await queryWithRetry(
            `UPDATE table_bill_splits
             SET status = 'PAID', paid_at = CURRENT_TIMESTAMP
             WHERE id = $1 AND status = 'CLAIMED'
             RETURNING id`,
            [splitId]
        );
        if (upd.rowCount === 0) {
            // Not CLAIMED anymore. If the claim was ABANDONED but the guest
            // paid anyway (checkout kept open past the TTL), the money IS
            // collected: resurrect the split when the bill still has room —
            // the sum trigger rejects the UPDATE if it doesn't.
            try {
                upd = await queryWithRetry(
                    `UPDATE table_bill_splits
                     SET status = 'PAID', paid_at = CURRENT_TIMESTAMP
                     WHERE id = $1 AND status = 'ABANDONED'
                     RETURNING id`,
                    [splitId]
                );
            } catch (resErr: any) {
                // Trigger refused: capacity was re-claimed and paid by
                // someone else → this is a real overpayment. Make it loud:
                // the staff must refund it by hand (until the dedicated
                // refund endpoint lands).
                console.error('[bill-split] OVERPAYMENT: split', splitId, 'paid after abandon, bill', billId, 'has no capacity left:', resErr?.message);
                pushSendToRoles(tenantId, ['OWNER', 'GENERAL_MANAGER', 'MANAGER'], {
                    category: 'payment',
                    title: 'Pagamento in eccesso da rimborsare',
                    body: `${formatEuroMinor(amount)} pagati su un conto già saldato (conto #${billId}). Serve un rimborso manuale da Revolut.`,
                    url: `/?view=PAGAMENTI`,
                    tag: `bill-overpaid-${splitId}`,
                }, { excludeUserId: null }).catch(() => {});
                return;
            }
            if (upd.rowCount === 0) {
                // Already PAID (webhook replay) or RELEASED/REFUNDED —
                // nothing to do.
                return;
            }
        }

        try {
            socketService?.broadcastToAll(tenantId, 'bill:split-paid', {
                bill_id: billId, split_id: splitId, amount_cents: amount,
            });
        } catch (_) {}

        // SETTLED promotion: total_cents == sum of PAID splits. Guard on
        // status IN OPEN/LOCKED so a manually-closed bill doesn't get
        // clobbered. Race-safe because it's a single UPDATE ... WHERE
        // comparing against a sub-select computed atomically by PG.
        const settled = await queryWithRetry(
            `UPDATE table_bills b
             SET status = 'SETTLED'
             WHERE b.id = $1
               AND b.tenant_id = $2
               AND b.status IN ('OPEN','LOCKED')
               AND b.total_cents = (
                   SELECT COALESCE(SUM(amount_cents), 0)
                   FROM table_bill_splits
                   WHERE table_bill_id = $1 AND status = 'PAID'
               )
             RETURNING id, reservation_id, table_id, total_cents, covers, status`,
            [billId, tenantId]
        );
        if ((settled.rowCount ?? 0) > 0) {
            try { socketService?.broadcastToAll(tenantId, 'bill:settled', settled.rows[0]); } catch (_) {}
        }
        return;
    }

    if (event === 'ORDER_CANCELLED' || event === 'ORDER_PAYMENT_DECLINED' || event === 'ORDER_PAYMENT_FAILED') {
        const upd = await queryWithRetry(
            `UPDATE table_bill_splits
             SET status = 'ABANDONED'
             WHERE id = $1 AND status = 'CLAIMED'
             RETURNING id`,
            [splitId]
        );
        if ((upd.rowCount ?? 0) > 0) {
            try {
                socketService?.broadcastToAll(tenantId, 'bill:split-abandoned', {
                    bill_id: billId, split_id: splitId,
                });
            } catch (_) {}
        }
    }
}

// Shared side-effect pipeline for a payment order state change, in the
// provider-neutral ORDER_* vocabulary (see services/paymentProviderService.ts
// — SumUp's PAID/FAILED/EXPIRED are normalised onto it before they get here).
// Called by both webhook receivers and the manual reconcile endpoint.
// Idempotent: gated on `completed_at` under a row-level lock so replaying an
// already-processed transition is a no-op — customer confirmation fires only
// on the FIRST ORDER_COMPLETED, no matter how many times we're called.
//
// `extraMetadata` is merged into payment_requests.metadata when present; it
// carries provider details we only learn at transition time (the SumUp
// transaction id, which later refunds are keyed on).
type PaymentTransitionResult =
    | { status: 'applied'; row: any; isFirstCompletion: boolean }
    | { status: 'ignored'; reason: string };
async function applyPaymentOrderTransition(
    orderId: string,
    event: string,
    extraMetadata?: Record<string, unknown> | null
): Promise<PaymentTransitionResult> {
    let nextStatus: string | null = null;
    let markCompleted = false;
    switch (event) {
        case 'ORDER_COMPLETED':
            nextStatus = 'COMPLETED';
            markCompleted = true;
            break;
        case 'ORDER_AUTHORISED':
            nextStatus = 'AUTHORISED';
            break;
        case 'ORDER_CANCELLED':
            nextStatus = 'CANCELLED';
            break;
        case 'ORDER_PAYMENT_DECLINED':
        case 'ORDER_PAYMENT_FAILED':
            nextStatus = 'FAILED';
            break;
        default:
            console.log('[payments] unhandled event:', event);
            return { status: 'ignored', reason: event };
    }

    const client = await pool.connect();
    let row: any;
    let wasCompleted = false;
    try {
        await client.query('BEGIN');
        const before = await client.query(
            `SELECT id, status, completed_at, reservation_id
             FROM payment_requests WHERE provider_order_id = $1 FOR UPDATE`,
            [orderId]
        );
        if (before.rowCount === 0) {
            await client.query('ROLLBACK');
            console.warn('[payments] transition: no payment_request found for order_id', orderId);
            return { status: 'ignored', reason: 'unknown order' };
        }
        wasCompleted = before.rows[0].completed_at !== null;
        const updated = await client.query(
            `UPDATE payment_requests
             SET status = $1,
                 completed_at = CASE WHEN $2 AND completed_at IS NULL THEN CURRENT_TIMESTAMP ELSE completed_at END,
                 metadata = CASE WHEN $3::jsonb IS NULL THEN metadata
                                 ELSE COALESCE(metadata, '{}'::jsonb) || $3::jsonb END,
                 updated_at = CURRENT_TIMESTAMP
             WHERE id = $4
             RETURNING *`,
            [
                nextStatus,
                markCompleted,
                extraMetadata && Object.keys(extraMetadata).length > 0 ? JSON.stringify(extraMetadata) : null,
                before.rows[0].id,
            ]
        );
        row = updated.rows[0];
        await client.query('COMMIT');
    } catch (err) {
        await client.query('ROLLBACK').catch(() => {});
        throw err;
    } finally {
        client.release();
    }

    try { socketService?.broadcastToAll(Number(row.tenant_id) || PUBLIC_TENANT_ID, 'paymentRequest:updated', row); }
    catch (err) { console.warn('[payments] socket broadcast failed:', (err as any)?.message || err); }

    // Keep the booking card's payment badge live on webhook transitions
    // (paid/failed/expired land without any operator action).
    if (row.reservation_id) broadcastReservationsUpdatedByIds([row.reservation_id]).catch(() => {});

    const isFirstCompletion = markCompleted && !wasCompleted;
    const billSplitId: number | null = row.table_bill_split_id ?? null;

    // Bill split side effects: if the payment is attached to a
    // table_bill_splits row, propagate the transition. Runs on both
    // first-completion (mark PAID + check SETTLED) and on
    // cancelled/failed (mark ABANDONED so the capacity is freed).
    if (billSplitId) {
        try {
            // Il tenant viaggia con la riga payment_requests appena aggiornata.
            await applyBillSplitTransition(Number(row.tenant_id) || PUBLIC_TENANT_ID, billSplitId, event, isFirstCompletion);
        } catch (err: any) {
            console.error('[payments] bill split transition failed for split', billSplitId, err?.message || err);
        }
    }

    // The deposit-confirmation flow below is only for prenotazione
    // deposits, not for pay-at-table splits — the split guest doesn't
    // want a "grazie, la tua prenotazione è confermata" WhatsApp.
    if (isFirstCompletion && !billSplitId) {
        const bodyLine = `${formatEuroMinor(row.amount_cents)} da prenotazione #${row.reservation_id ?? '?'}`;
        // La push arriva allo staff del ristorante della payment_request.
        pushSendToRoles(Number(row.tenant_id) || PUBLIC_TENANT_ID, ['OWNER', 'GENERAL_MANAGER', 'MANAGER'], {
            category: 'payment',
            title: 'Pagamento ricevuto',
            body: bodyLine,
            url: row.reservation_id ? `/?view=RESERVATIONS&reservationId=${row.reservation_id}` : `/?view=RESERVATIONS`,
            tag: `payment-${row.id}`,
        }, { excludeUserId: null }).catch(err => {
            console.warn('[payments] push send failed:', err?.message || err);
        });
    }

    if (isFirstCompletion && row.reservation_id && !billSplitId) {
        (async () => {
            try {
                // Niente JWT qui (webhook/riconciliatore): la prenotazione è
                // quella del tenant della payment_request, mai di un altro.
                const resvRes = await queryWithRetry(
                    `SELECT id, customer_name, phone, reservation_time, guests,
                            reservation_status, table_id, notes
                     FROM reservations WHERE id = $1 AND tenant_id = $2`,
                    [row.reservation_id, row.tenant_id]
                );
                if (resvRes.rowCount === 0) return;
                const reservation = resvRes.rows[0];

                if (reservation.reservation_status === 'PENDING') {
                    const upd = await queryWithRetry(
                        `UPDATE reservations
                         SET reservation_status = 'CONFIRMED',
                             updated_at = CURRENT_TIMESTAMP
                         WHERE id = $1 AND tenant_id = $2
                         RETURNING *`,
                        [reservation.id, row.tenant_id]
                    );
                    if (upd.rows[0] && socketService) {
                        try { socketService.broadcastReservationUpdated(Number(row.tenant_id) || PUBLIC_TENANT_ID, upd.rows[0]); }
                        catch (err) { console.warn('[payments] reservation broadcast failed:', err); }
                    }
                }

                if (reservation.phone &&
                    (reservation.reservation_status === 'PENDING' ||
                     reservation.reservation_status === 'CONFIRMED')) {
                    const roomName = await resolveReservationRoomName(reservation);
                    const message = buildDepositConfirmationMessage(
                        reservation.customer_name,
                        reservation.reservation_time,
                        reservation.guests,
                        row.amount_cents,
                        roomName
                    );
                    // Transizione invocata sia da webhook sia da riconciliatore:
                    // niente JWT in mano, il tenant è quello della payment_request.
                    await sendBookingConfirmation(Number(row.tenant_id) || PUBLIC_TENANT_ID, reservation.phone, message, reservation.id, {
                        whatsappTemplate: buildBookingDepositConfirmedTemplate(
                            reservation.customer_name,
                            reservation.reservation_time,
                            reservation.guests,
                            row.amount_cents
                        ),
                    });
                }
            } catch (err: any) {
                console.error('[payments] deposit confirmation flow failed:', err?.message || err);
            }
        })();
    }

    // Se un conto è GIÀ aperto per questa prenotazione, porta subito dentro
    // l'acconto appena incassato. Il caso normale (conto aperto dopo il
    // pagamento) è coperto all'apertura conto; questo copre l'ordine inverso.
    if (isFirstCompletion && row.reservation_id && !billSplitId) {
        (async () => {
            try {
                // Il conto è quello del tenant della payment_request: gli id
                // prenotazione sono globali, senza filtro si aggancerebbe il
                // conto di un altro ristorante.
                const prTenantId = Number(row.tenant_id) || PUBLIC_TENANT_ID;
                const billRs = await queryWithRetry(
                    `SELECT id FROM table_bills
                     WHERE reservation_id = $1 AND tenant_id = $2 AND status IN ('OPEN', 'LOCKED')
                     ORDER BY opened_at DESC LIMIT 1`,
                    [row.reservation_id, prTenantId]
                );
                if ((billRs.rowCount ?? 0) === 0) return;
                const billId = billRs.rows[0].id;
                const credit = await creditPaidDepositsToBill(prTenantId, billId);
                if (credit.credited > 0 || credit.settled) {
                    try {
                        socketService?.broadcastToAll(prTenantId, 'bill:updated', { id: billId, reservation_id: row.reservation_id });
                        if (credit.settled) {
                            const v = await loadBillView(prTenantId, billId);
                            if (v?.bill) socketService?.broadcastToAll(prTenantId, 'bill:settled', v.bill);
                        }
                    } catch (_) {}
                }
            } catch (err: any) {
                console.error('[deposit-credit] post-completion crediting failed:', err?.message || err);
            }
        })();
    }

    return { status: 'applied', row, isFirstCompletion };
}

// Revolut webhook receiver. HMAC signature is validated against the raw
// request body captured by the global express.json verify hook. Idempotent:
// duplicate events (Revolut retries until 2xx) update the same row without
// side-effects because we key on `provider_order_id` and gate the
// "first-completion" side-effects on the old `completed_at` being NULL under
// a row-level lock.
app.post('/webhook/revolut', async (req, res) => {
    try {
        const body = req.body || {};
        const event = String(body.event || '').toUpperCase();
        const orderId: string | undefined = body.order_id || body.data?.order_id || body.data?.id;

        // Prima si risale al tenant dall'order_id (lookup globale su
        // provider_order_id: È il meccanismo con cui il webhook trova la
        // riga), POI si verifica la firma col segreto di QUEL ristorante.
        // Ordine senza riga (o order_id assente): si ripiega sul segreto del
        // tenant storico — resta così finché la Fase C2 non dà a ogni tenant
        // il proprio endpoint webhook.
        let webhookTenantId = PUBLIC_TENANT_ID;
        if (orderId) {
            const t = await queryWithRetry(
                `SELECT tenant_id FROM payment_requests WHERE provider_order_id = $1 LIMIT 1`,
                [orderId]
            ).catch(() => ({ rows: [] as any[] }));
            if (t.rows[0]?.tenant_id != null) webhookTenantId = Number(t.rows[0].tenant_id);
        }

        const verification = await verifyRevolutWebhook(webhookTenantId, req);
        if (!verification.valid) {
            console.warn('[Revolut] webhook rejected:', verification.reason);
            return res.status(401).json({ error: 'invalid signature', reason: verification.reason });
        }

        if (!orderId) {
            console.warn('[Revolut] webhook missing order_id, event=', event);
            return res.status(200).json({ ok: true, ignored: 'missing order_id' });
        }

        const result = await applyPaymentOrderTransition(orderId, event);
        if (result.status === 'ignored') return res.status(200).json({ ok: true, ignored: result.reason });
        return res.status(200).json({ ok: true });
    } catch (err: any) {
        console.error('POST /webhook/revolut error:', err);
        res.status(500).json({ error: 'Internal server error', detail: err?.message });
    }
});

// SumUp callback receiver. SumUp pings the `return_url` we register on each
// checkout when its status changes, but — unlike Revolut — that request is
// NOT signed, so nothing in the body can be trusted. Two defences:
//
//  1. the URL carries an opaque token only we and SumUp know, compared in
//     constant time (cheap filter against random internet traffic);
//  2. the body is used solely to learn WHICH checkout moved. The status is
//     then re-read from SumUp's API, so a forged payload can at worst make
//     us re-check a checkout, never mark one paid.
//
// Idempotent for the same reason the Revolut receiver is: we key on
// provider_order_id and gate first-completion side-effects on completed_at.
app.post('/webhook/sumup/:token', async (req, res) => {
    try {
        // SumUp has shipped a few payload shapes over the years (and wraps
        // the resource under `payload`/`data` in some of them), so probe the
        // plausible spots rather than pinning one.
        const body = req.body || {};
        const checkoutId: string | undefined =
            body.id || body.checkout_id ||
            body.payload?.id || body.payload?.checkout_id ||
            body.data?.id || body.data?.checkout_id;

        // Prima il tenant dal checkout id (lookup globale su
        // provider_order_id, come per Revolut), POI il confronto col token di
        // callback di QUEL ristorante. Il body qui serve solo a capire QUALE
        // riga si è mossa — lo stato viene comunque riletto dall'API — quindi
        // usarlo per risolvere il tenant prima della verifica non allarga la
        // superficie. Senza riga si ripiega sul segreto del tenant storico,
        // finché la Fase C2 non dà a ogni tenant il proprio endpoint.
        let webhookTenantId = PUBLIC_TENANT_ID;
        if (checkoutId) {
            const t = await queryWithRetry(
                `SELECT tenant_id FROM payment_requests WHERE provider_order_id = $1 LIMIT 1`,
                [checkoutId]
            ).catch(() => ({ rows: [] as any[] }));
            if (t.rows[0]?.tenant_id != null) webhookTenantId = Number(t.rows[0].tenant_id);
        }

        const expected = await getSumUpCallbackSecret(webhookTenantId);
        if (!callbackTokenMatches(req.params.token, expected)) {
            console.warn('[SumUp] callback rejected: token mismatch');
            return res.status(401).json({ error: 'invalid token' });
        }

        if (!checkoutId) {
            console.warn('[SumUp] callback missing checkout id, body keys=', Object.keys(body));
            return res.status(200).json({ ok: true, ignored: 'missing checkout id' });
        }

        // Answer SumUp before doing the work: the status re-read plus the
        // downstream confirmation flow (WhatsApp/SMS) can take seconds, and a
        // slow 200 just earns us a retry storm. Failures are logged and the
        // reconcile paths (manual button, bill-split job) remain the backstop.
        res.status(200).json({ ok: true });

        try {
            const fetched = await fetchPaymentOrder(webhookTenantId, 'sumup', checkoutId);
            if (!fetched.event) {
                console.log('[SumUp] callback: checkout', checkoutId, 'still', fetched.state, '— nothing to apply');
                return;
            }
            await applyPaymentOrderTransition(
                checkoutId,
                fetched.event,
                transitionMetadata('sumup', fetched.raw)
            );
        } catch (err: any) {
            console.error('[SumUp] callback processing failed for checkout', checkoutId, err?.message || err);
        }
    } catch (err: any) {
        console.error('POST /webhook/sumup error:', err);
        if (!res.headersSent) res.status(500).json({ error: 'Internal server error', detail: err?.message });
    }
});

// Manual reconciliation: poll the gateway for the current state of the order
// associated with a payment_request and apply the corresponding transition.
// Used when a webhook was missed — e.g. an order created before the webhook
// endpoint existed, or a delivery the provider permanently gave up on. Same
// side-effects as the real webhook (broadcast + push + deposit confirmation)
// so the UI reflects reality after one click.
app.post('/payments/:id/reconcile', authenticate, requirePermission('payments:full'), async (req, res) => {
    try {
        const id = parseInt(req.params.id, 10);
        if (!Number.isFinite(id)) return res.status(400).json({ error: 'Invalid id' });

        const paymentRes = await queryWithRetry(
            // Scopato sul tenant: un payment id altrui fa 404 come inesistente.
            `SELECT id, provider, provider_order_id FROM payment_requests WHERE id = $1 AND tenant_id = $2`,
            [id, req.tenantId!]
        );
        if (paymentRes.rowCount === 0) return res.status(404).json({ error: 'Payment not found' });
        const payment = paymentRes.rows[0];

        // Reconcile through the provider that created the order, so a
        // payment opened before an operator switched gateways still resolves.
        if (!isPaymentProvider(payment.provider)) {
            return res.status(400).json({ error: `Reconcile non supportato per provider ${payment.provider}` });
        }
        const provider: PaymentProvider = payment.provider;
        const label = providerLabel(provider);
        if (!payment.provider_order_id) {
            return res.status(400).json({ error: 'Nessun order ID associato al pagamento' });
        }
        if (!(await isProviderConfigured(req.tenantId!, provider))) {
            return res.status(503).json({ error: `${label} non è configurato (credenziali mancanti)` });
        }

        let fetched;
        try {
            fetched = await fetchPaymentOrder(req.tenantId!, provider, payment.provider_order_id);
        } catch (err: any) {
            console.error('[payments] reconcile fetch failed:', err?.message || err);
            return res.status(502).json({ error: `Lettura ordine ${label} fallita`, detail: err?.message || String(err) });
        }

        if (!fetched.event) {
            return res.status(200).json({
                ok: true,
                changed: false,
                provider,
                provider_state: fetched.state,
                revolut_state: fetched.state,
                message: `Stato ${label} "${fetched.state}" non richiede aggiornamenti`,
            });
        }

        const result = await applyPaymentOrderTransition(
            payment.provider_order_id,
            fetched.event,
            transitionMetadata(provider, fetched.raw)
        );
        if (result.status === 'ignored') {
            return res.status(200).json({
                ok: true,
                changed: false,
                ignored: result.reason,
                provider,
                provider_state: fetched.state,
                revolut_state: fetched.state,
            });
        }

        return res.status(200).json({
            ok: true,
            changed: true,
            provider,
            provider_state: fetched.state,
            // Kept alongside provider_state so older clients that read
            // `revolut_state` keep rendering the reconcile result.
            revolut_state: fetched.state,
            first_completion: result.isFirstCompletion,
            payment_request: result.row,
        });
    } catch (err: any) {
        console.error('POST /payments/:id/reconcile error:', err);
        res.status(500).json({ error: 'Internal server error', detail: err?.message });
    }
});

// Full refund of a standalone payment request (a deposit / payment link).
// Split-linked payments deliberately go through /bills/splits/:id/refund
// instead: that path also reopens the bill when the refund drops it below
// its total, which this one has no business doing.
//
// Refund FIRST, then write: if the gateway refuses, nothing changed on our
// side. If the write failed after a successful refund the gateway's records
// remain the source of truth, and a retry is a no-op for us because the row
// is no longer in a refundable state.
app.post('/payments/:id/refund', authenticate, requirePermission('payments:full'), async (req, res) => {
    try {
        const id = parseInt(req.params.id, 10);
        if (!Number.isFinite(id)) return res.status(400).json({ error: 'Invalid id' });

        const paymentRes = await queryWithRetry(
            // Scopato sul tenant: un payment id altrui fa 404 come inesistente.
            `SELECT id, provider, provider_order_id, status, amount_cents, currency,
                    description, reservation_id, table_bill_split_id, metadata
             FROM payment_requests WHERE id = $1 AND tenant_id = $2`,
            [id, req.tenantId!]
        );
        if (paymentRes.rowCount === 0) return res.status(404).json({ error: 'Pagamento non trovato' });
        const payment = paymentRes.rows[0];

        if (payment.table_bill_split_id != null) {
            return res.status(409).json({
                error: 'Questo pagamento è una quota di un conto: usa il rimborso della quota, che riapre anche il conto',
            });
        }
        if (!['COMPLETED', 'PAID'].includes(String(payment.status || '').toUpperCase())) {
            return res.status(409).json({ error: `Il pagamento non è rimborsabile (stato ${payment.status})` });
        }
        if (!isPaymentProvider(payment.provider) || !payment.provider_order_id) {
            return res.status(409).json({ error: 'Nessun ordine di pagamento collegato' });
        }
        const provider: PaymentProvider = payment.provider;
        if (!(await isProviderConfigured(req.tenantId!, provider))) {
            return res.status(503).json({ error: `${providerLabel(provider)} non è configurato (credenziali mancanti)` });
        }

        try {
            await refundPaymentOrder(
                req.tenantId!,
                provider,
                payment.provider_order_id,
                payment.amount_cents,
                payment.currency || 'EUR',
                payment.description || `Rimborso pagamento #${payment.id}`,
                // Captured when the payment completed; SumUp refunds are keyed
                // on the transaction, not the checkout.
                payment.metadata?.sumup_transaction_id ?? null
            );
        } catch (err: any) {
            console.error('[payments] refund failed:', err?.message || err);
            // The provider services already produce an operator-readable
            // reason; use it as the message rather than burying it behind a
            // generic wrapper, which read as "Rimborso SumUp fallito: SumUp
            // ha rifiutato il rimborso: …" in the UI banner.
            const reason = err?.message ? String(err.message) : '';
            return res.status(502).json({
                error: reason || `Rimborso ${providerLabel(provider)} fallito`,
                detail: reason ? undefined : String(err),
            });
        }

        const updated = await queryWithRetry(
            `UPDATE payment_requests
             SET status = 'REFUNDED', updated_at = CURRENT_TIMESTAMP
             WHERE id = $1
             RETURNING *`,
            [payment.id]
        );
        const row = updated.rows[0];

        try { socketService?.broadcastToAll(req.tenantId!, 'paymentRequest:updated', row); }
        catch (err) { console.warn('[payments] refund broadcast failed:', (err as any)?.message || err); }

        if (row.reservation_id) broadcastReservationsUpdatedByIds([row.reservation_id]).catch(() => {});

        // Se questo acconto era stato accreditato su un conto, storna il credito:
        // la quota deposit torna REFUNDED (esce da paid_cents → il residuo risale)
        // e se il conto era SETTLED solo grazie all'acconto, si riapre.
        try {
            const revoked = await queryWithRetry(
                `UPDATE table_bill_splits
                 SET status = 'REFUNDED', released_at = CURRENT_TIMESTAMP
                 WHERE payment_request_id = $1 AND tenant_id = $2 AND kind = 'deposit' AND status = 'PAID'
                 RETURNING table_bill_id`,
                [payment.id, req.tenantId!]
            );
            for (const s of revoked.rows) {
                const reopened = await queryWithRetry(
                    `UPDATE table_bills SET status = 'OPEN', closed_at = NULL
                     WHERE id = $1 AND tenant_id = $2 AND status = 'SETTLED'
                       AND total_cents > (SELECT COALESCE(SUM(amount_cents), 0) FROM table_bill_splits WHERE table_bill_id = $1 AND status = 'PAID')
                     RETURNING *`,
                    [s.table_bill_id, req.tenantId!]
                );
                try {
                    socketService?.broadcastToAll(req.tenantId!, 'bill:split-refunded', { bill_id: s.table_bill_id });
                    if ((reopened.rowCount ?? 0) > 0) socketService?.broadcastToAll(req.tenantId!, 'bill:opened', reopened.rows[0]);
                    else socketService?.broadcastToAll(req.tenantId!, 'bill:updated', { id: s.table_bill_id });
                } catch (_) {}
            }
        } catch (err) {
            console.error('[deposit-credit] refund reversal failed for payment', payment.id, (err as any)?.message || err);
        }

        if (req.user) {
            LogService.logActivity(
                req.tenantId!,
                req.user.userId,
                req.user.email,
                req.user.email,
                ActivityAction.UPDATE,
                ResourceType.RESERVATION,
                payment.reservation_id ?? undefined,
                `Rimborso ${formatEuroMinor(payment.amount_cents)} (${providerLabel(provider)}) — pagamento #${payment.id}`
            );
        }

        // Tell the guest their money is on the way back. Fire-and-forget on
        // purpose: the refund already went through at the gateway, so a
        // Twilio hiccup must not turn a successful refund into a 5xx. The
        // send is recorded in outbound_messages either way, so it shows up in
        // the payment's "Comunicazioni con il cliente" timeline.
        if (payment.reservation_id) {
            (async () => {
                try {
                    const resv = await queryWithRetry(
                        'SELECT customer_name, phone, reservation_time FROM reservations WHERE id = $1 AND tenant_id = $2',
                        [payment.reservation_id, req.tenantId!]
                    );
                    const reservation = resv.rows[0];
                    if (!reservation?.phone) return;
                    const message = buildRefundNotificationMessage(
                        reservation.customer_name,
                        payment.amount_cents,
                        reservation.reservation_time
                    );
                    // No Meta-approved template exists for refunds, so this
                    // goes out as SMS (sendBookingConfirmation only attempts
                    // WhatsApp when given a template).
                    const delivery = await sendBookingConfirmation(req.tenantId!, reservation.phone, message, payment.reservation_id);
                    console.log(`[payments] refund notice sent for payment ${payment.id} via ${delivery.channel}`);
                } catch (err: any) {
                    console.error('[payments] refund notice failed for payment', payment.id, err?.message || err);
                }
            })();
        }

        res.json({ ok: true, payment_request: row });
    } catch (err: any) {
        console.error('POST /payments/:id/refund error:', err);
        res.status(500).json({ error: 'Internal server error', detail: err?.message });
    }
});


// Tables - require authentication
app.get('/tables', authenticate, async (req, res) => {
    try {
        const result = await queryWithRetry('SELECT * FROM tables WHERE tenant_id = $1 ORDER BY name', [req.tenantId!]);
        res.json(result.rows);
    } catch (err) {
        console.error(err);
        res.status(500).json({ error: 'Internal server error' });
    }
});

app.post('/tables', authenticate, requirePermission('floorplan:full'), async (req, res) => {
    try {
        const { name, shape, seats, x, y, room_id, status, rotation } = req.body;
        // La sala dev'essere del tenant: senza questo check un room_id altrui
        // aggancerebbe il tavolo alla pianta di un altro ristorante.
        if (room_id != null) {
            const room = await queryWithRetry('SELECT id FROM rooms WHERE id = $1 AND tenant_id = $2', [room_id, req.tenantId!]);
            if (room.rowCount === 0) return res.status(404).json({ error: 'Room not found' });
        }
        const result = await queryWithRetry(
            'INSERT INTO tables (tenant_id, name, shape, seats, x, y, room_id, status, rotation) VALUES ($9, $1, $2, $3, $4, $5, $6, $7, $8) RETURNING *',
            [name, shape, seats, x, y, room_id, status, rotation || 0, req.tenantId!]
        );
        const newTable = result.rows[0];

        // Log activity
        if (req.user) {
            LogService.logActivity(
                req.tenantId!,
                req.user.userId,
                req.user.email,
                req.user.email,
                ActivityAction.CREATE,
                ResourceType.TABLE,
                newTable.id,
                name,
                { shape, seats, room_id }
            );
        }

        // Broadcast to all connected clients except the one who created it
        const socketId = req.headers['x-socket-id'] as string;
        if (socketService) socketService.broadcastTableCreated(req.tenantId!, newTable, socketId);

        res.status(201).json(newTable);
    } catch (err) {
        console.error(err);
        res.status(500).json({ error: 'Internal server error' });
    }
});

app.put('/tables/:id', authenticate, requirePermission('floorplan:update_status'), async (req, res) => {
    try {
        const { id } = req.params;

        console.log('PUT /tables/:id - Request body:', JSON.stringify(req.body, null, 2));

        // Build dynamic update query based on provided fields
        const fields: string[] = [];
        const values: any[] = [];
        let paramIndex = 1;

        const allowedFields = ['name', 'shape', 'seats', 'x', 'y', 'room_id', 'status', 'is_locked', 'merged_with', 'temp_lock_expires_at', 'rotation', 'width_cm', 'length_cm', 'notes'];

        allowedFields.forEach(field => {
            if (req.body.hasOwnProperty(field)) {
                fields.push(`${field} = $${paramIndex}`);

                // Special handling for merged_with - ensure it's null if undefined/empty
                if (field === 'merged_with') {
                    const mergedWith = req.body[field];
                    values.push(mergedWith && Array.isArray(mergedWith) && mergedWith.length > 0 ? mergedWith : null);
                    console.log('Setting merged_with to:', values[values.length - 1]);
                } else {
                    values.push(req.body[field]);
                }

                paramIndex++;
            }
        });

        if (fields.length === 0) {
            return res.status(400).json({ error: 'No fields to update' });
        }

        // room_id arriva dal body: senza il check per tenant un id altrui
        // sposterebbe il tavolo nella pianta di un altro ristorante.
        if (req.body.room_id != null) {
            const room = await queryWithRetry('SELECT id FROM rooms WHERE id = $1 AND tenant_id = $2', [req.body.room_id, req.tenantId!]);
            if (room.rowCount === 0) return res.status(404).json({ error: 'Room not found' });
        }

        values.push(id);
        values.push(req.tenantId!);
        const query = `UPDATE tables SET ${fields.join(', ')} WHERE id = $${paramIndex} AND tenant_id = $${paramIndex + 1} RETURNING *`;

        console.log('SQL Query:', query);
        console.log('Values:', values);

        const result = await queryWithRetry(query, values);
        const updatedTable = result.rows[0];
        if (!updatedTable) {
            return res.status(404).json({ error: 'Table not found' });
        }

        console.log('Updated table merged_with:', updatedTable.merged_with);

        // Log activity
        if (req.user) {
            LogService.logActivity(
                req.tenantId!,
                req.user.userId,
                req.user.email,
                req.user.email,
                ActivityAction.UPDATE,
                ResourceType.TABLE,
                parseInt(id, 10),
                updatedTable.name,
                req.body
            );
        }

        // Broadcast to all connected clients
        const socketId = req.headers['x-socket-id'] as string;
        if (socketService) socketService.broadcastTableUpdated(req.tenantId!, updatedTable, socketId);

        res.json(updatedTable);
    } catch (err) {
        console.error('Error updating table:', err);
        res.status(500).json({ error: 'Internal server error' });
    }
});

app.delete('/tables/:id', authenticate, requirePermission('floorplan:full'), async (req, res) => {
    try {
        const { id } = req.params;

        // Get table name before deleting
        const existing = await queryWithRetry('SELECT name FROM tables WHERE id = $1 AND tenant_id = $2', [id, req.tenantId!]);
        const resourceName = existing.rows[0]?.name;

        await queryWithRetry('DELETE FROM tables WHERE id = $1 AND tenant_id = $2', [id, req.tenantId!]);

        // Log activity
        if (req.user) {
            LogService.logActivity(
                req.tenantId!,
                req.user.userId,
                req.user.email,
                req.user.email,
                ActivityAction.DELETE,
                ResourceType.TABLE,
                parseInt(id, 10),
                resourceName
            );
        }

        // Broadcast to all connected clients
        if (socketService) socketService.broadcastTableDeleted(req.tenantId!, Number(id));

        res.status(204).send();
    } catch (err) {
        console.error(err);
        res.status(500).json({ error: 'Internal server error' });
    }
});


// ============================================
// PER-SHIFT TABLE MERGES
// ============================================

// GET /table-merges?date=YYYY-MM-DD&shift=LUNCH|DINNER
app.get('/table-merges', authenticate, async (req, res) => {
    try {
        const { date, shift } = req.query;
        if (!date || !shift) {
            return res.status(400).json({ error: 'date and shift query params are required' });
        }
        if (shift !== 'LUNCH' && shift !== 'DINNER') {
            return res.status(400).json({ error: 'shift must be LUNCH or DINNER' });
        }
        const result = await queryWithRetry(
            'SELECT id, date, shift, primary_id, merged_ids FROM table_merges WHERE date = $1 AND shift = $2 AND tenant_id = $3',
            [date, shift, req.tenantId!]
        );
        res.json(result.rows);
    } catch (err) {
        console.error('Error fetching table merges:', err);
        res.status(500).json({ error: 'Internal server error' });
    }
});

// POST /table-merges  body: { date, shift, primary_id, merged_ids }
// Idempotent — replaces an existing merge for the same (date, shift, primary_id).
app.post('/table-merges', authenticate, requirePermission('floorplan:full'), async (req, res) => {
    try {
        const { date, shift, primary_id, merged_ids } = req.body;
        if (!date || !shift || primary_id == null || !Array.isArray(merged_ids) || merged_ids.length === 0) {
            return res.status(400).json({ error: 'date, shift, primary_id and non-empty merged_ids are required' });
        }
        if (shift !== 'LUNCH' && shift !== 'DINNER') {
            return res.status(400).json({ error: 'shift must be LUNCH or DINNER' });
        }
        // Tutti i tavoli coinvolti devono essere del tenant PRIMA dell'upsert:
        // il vincolo resta (date, shift, primary_id), quindi un primary_id
        // altrui farebbe DO UPDATE sull'unione di un altro ristorante.
        const allIds = [primary_id, ...merged_ids];
        const owned = await queryWithRetry(
            'SELECT id FROM tables WHERE id = ANY($1::int[]) AND tenant_id = $2',
            [allIds, req.tenantId!]
        );
        if ((owned.rowCount ?? 0) !== new Set(allIds).size) {
            return res.status(404).json({ error: 'Table not found' });
        }
        const result = await queryWithRetry(
            `INSERT INTO table_merges (tenant_id, date, shift, primary_id, merged_ids)
             VALUES ($5, $1, $2, $3, $4)
             ON CONFLICT (date, shift, primary_id)
             DO UPDATE SET merged_ids = EXCLUDED.merged_ids
             RETURNING id, date, shift, primary_id, merged_ids`,
            [date, shift, primary_id, merged_ids, req.tenantId!]
        );
        const merge = result.rows[0];

        if (req.user) {
            LogService.logActivity(
                req.tenantId!,
                req.user.userId,
                req.user.email,
                req.user.email,
                ActivityAction.CREATE,
                ResourceType.TABLE,
                primary_id,
                `Merge ${date} ${shift}`,
                { date, shift, merged_ids }
            );
        }

        // Broadcast to ALL clients (including originator) so the originating
        // client's local merge state updates from the socket event without
        // needing an extra refetch. The client listener upserts idempotently.
        if (socketService) socketService.broadcastTableMergeCreated(req.tenantId!, merge);

        res.status(201).json(merge);
    } catch (err) {
        console.error('Error creating table merge:', err);
        res.status(500).json({ error: 'Internal server error' });
    }
});

// DELETE /table-merges  body: { date, shift, primary_id }
app.delete('/table-merges', authenticate, requirePermission('floorplan:full'), async (req, res) => {
    try {
        const { date, shift, primary_id } = req.body;
        if (!date || !shift || primary_id == null) {
            return res.status(400).json({ error: 'date, shift and primary_id are required' });
        }
        const result = await queryWithRetry(
            `DELETE FROM table_merges
             WHERE date = $1 AND shift = $2 AND primary_id = $3 AND tenant_id = $4
             RETURNING id, date, shift, primary_id, merged_ids`,
            [date, shift, primary_id, req.tenantId!]
        );
        if (result.rowCount === 0) {
            return res.status(404).json({ error: 'Merge not found' });
        }
        const deleted = result.rows[0];

        if (req.user) {
            LogService.logActivity(
                req.tenantId!,
                req.user.userId,
                req.user.email,
                req.user.email,
                ActivityAction.DELETE,
                ResourceType.TABLE,
                primary_id,
                `Unmerge ${date} ${shift}`,
                { date, shift }
            );
        }

        if (socketService) socketService.broadcastTableMergeDeleted(req.tenantId!, deleted);

        res.json(deleted);
    } catch (err) {
        console.error('Error deleting table merge:', err);
        res.status(500).json({ error: 'Internal server error' });
    }
});


// ============================================
// PER-SHIFT HIDDEN TABLES
// ============================================

// GET /table-hidden?date=YYYY-MM-DD&shift=LUNCH|DINNER
// If neither param is supplied, returns future overrides (or all with scope=all)
// ordered by (date, shift) — used by the "Chiusure programmate" panel.
app.get('/table-hidden', authenticate, async (req, res) => {
    try {
        const { date, shift, scope } = req.query;
        if (date || shift) {
            if (!date || !shift) {
                return res.status(400).json({ error: 'date and shift query params are required together' });
            }
            if (shift !== 'LUNCH' && shift !== 'DINNER') {
                return res.status(400).json({ error: 'shift must be LUNCH or DINNER' });
            }
            const result = await queryWithRetry(
                'SELECT id, date, shift, table_id FROM table_hidden_overrides WHERE date = $1 AND shift = $2 AND tenant_id = $3',
                [date, shift, req.tenantId!]
            );
            return res.json(result.rows);
        }
        const whereClause = scope === 'all' ? 'WHERE tenant_id = $1' : 'WHERE tenant_id = $1 AND date >= CURRENT_DATE';
        const result = await queryWithRetry(
            `SELECT id, date, shift, table_id FROM table_hidden_overrides ${whereClause}
             ORDER BY date ASC, shift ASC`,
            [req.tenantId!]
        );
        res.json(result.rows);
    } catch (err) {
        console.error('Error fetching hidden tables:', err);
        res.status(500).json({ error: 'Internal server error' });
    }
});

// POST /table-hidden body: { date, shift, table_id }
// Refuses to hide a table that has a reservation or is in an active merge
// for the same (date, shift) — caller must reassign/split first.
app.post('/table-hidden', authenticate, requirePermission('floorplan:full'), async (req, res) => {
    try {
        const { date, shift, table_id } = req.body;
        if (!date || !shift || table_id == null) {
            return res.status(400).json({ error: 'date, shift and table_id are required' });
        }
        if (shift !== 'LUNCH' && shift !== 'DINNER') {
            return res.status(400).json({ error: 'shift must be LUNCH or DINNER' });
        }

        // Il tavolo dev'essere del tenant PRIMA dell'upsert: il vincolo resta
        // (date, shift, table_id), quindi un table_id altrui farebbe
        // DO UPDATE sull'override di un altro ristorante.
        const tbl = await queryWithRetry('SELECT id FROM tables WHERE id = $1 AND tenant_id = $2', [table_id, req.tenantId!]);
        if (tbl.rowCount === 0) return res.status(404).json({ error: 'Table not found' });

        // Block if a reservation is on this table for the given date+shift.
        const reservationCheck = await queryWithRetry(
            `SELECT id, customer_name FROM reservations
             WHERE tenant_id = $4
               AND table_id = $1
               AND shift = $2
               AND DATE(reservation_time AT TIME ZONE 'Europe/Rome') = $3`,
            [table_id, shift, date, req.tenantId!]
        );
        if (reservationCheck.rowCount && reservationCheck.rowCount > 0) {
            return res.status(409).json({
                error: 'Tavolo con prenotazioni',
                detail: `Il tavolo ha ${reservationCheck.rowCount} prenotazione/i per questo turno. Riassegnale prima di nascondere il tavolo.`,
                blocking_reservation_ids: reservationCheck.rows.map((r: any) => r.id),
            });
        }

        // Block if the table participates in an active merge for the given date+shift,
        // either as primary or inside merged_ids.
        const mergeCheck = await queryWithRetry(
            `SELECT id, primary_id, merged_ids FROM table_merges
             WHERE date = $1 AND shift = $2 AND tenant_id = $4 AND ($3 = primary_id OR $3 = ANY(merged_ids))`,
            [date, shift, table_id, req.tenantId!]
        );
        if (mergeCheck.rowCount && mergeCheck.rowCount > 0) {
            return res.status(409).json({
                error: 'Tavolo unito',
                detail: 'Il tavolo fa parte di un\'unione attiva per questo turno. Dividi prima di nascondere.',
            });
        }

        const result = await queryWithRetry(
            `INSERT INTO table_hidden_overrides (tenant_id, date, shift, table_id)
             VALUES ($4, $1, $2, $3)
             ON CONFLICT (date, shift, table_id) DO UPDATE SET date = EXCLUDED.date
             RETURNING id, date, shift, table_id`,
            [date, shift, table_id, req.tenantId!]
        );
        const hidden = result.rows[0];

        if (req.user) {
            LogService.logActivity(
                req.tenantId!,
                req.user.userId,
                req.user.email,
                req.user.email,
                ActivityAction.CREATE,
                ResourceType.TABLE,
                table_id,
                `Hide ${date} ${shift}`,
                { date, shift }
            );
        }

        if (socketService) socketService.broadcastTableHiddenCreated(req.tenantId!, hidden);

        res.status(201).json(hidden);
    } catch (err) {
        console.error('Error hiding table:', err);
        res.status(500).json({ error: 'Internal server error' });
    }
});

