// Create time off
app.post('/staff/time-off', authenticate, requirePermission('staff:full'), async (req, res) => {
    try {
        const { staffId, startDate, endDate, type, shift, notes, approved } = req.body;

        if (!staffId || !startDate || !endDate || !type) {
            return res.status(400).json({ error: 'staffId, startDate, endDate, and type are required' });
        }

        if (shift && shift !== 'LUNCH' && shift !== 'DINNER') {
            return res.status(400).json({ error: 'shift must be LUNCH, DINNER, or null' });
        }

        // Lo staff deve appartenere al tenant: senza il controllo si potrebbe
        // registrare un'assenza per un dipendente di un altro ristorante.
        if (!STAFF_UUID_RE.test(String(staffId))) {
            return res.status(404).json({ error: 'Staff member not found' });
        }
        const staffCheck = await queryWithRetry(
            'SELECT id FROM staff_members WHERE id = $1 AND tenant_id = $2',
            [staffId, req.tenantId!]
        );
        if (staffCheck.rows.length === 0) {
            return res.status(404).json({ error: 'Staff member not found' });
        }

        const result = await queryWithRetry(
            `INSERT INTO staff_time_off (tenant_id, staff_id, start_date, end_date, type, shift, notes, approved)
             VALUES ($8, $1, $2, $3, $4, $5, $6, $7)
             RETURNING *`,
            [staffId, startDate, endDate, type, shift || null, notes || null, approved !== false, req.tenantId!]
        );

        const row = result.rows[0];
        const timeOff = {
            id: row.id,
            staffId: row.staff_id,
            startDate: row.start_date,
            endDate: row.end_date,
            type: row.type,
            shift: row.shift,
            notes: row.notes,
            approved: row.approved,
            createdAt: row.created_at
        };

        // Broadcast
        const socketId = req.headers['x-socket-id'] as string;
        if (socketService) socketService.broadcastToAll(req.tenantId!, 'timeoff:created', timeOff, socketId);

        res.status(201).json(timeOff);
    } catch (err) {
        console.error(err);
        res.status(500).json({ error: 'Internal server error' });
    }
});

// Update time off
app.put('/staff/time-off/:id', authenticate, requirePermission('staff:full'), async (req, res) => {
    try {
        const { id } = req.params;
        const { startDate, endDate, type, shift, notes, approved } = req.body;

        if (shift !== undefined && shift !== null && shift !== 'LUNCH' && shift !== 'DINNER') {
            return res.status(400).json({ error: 'shift must be LUNCH, DINNER, or null' });
        }

        // shift is set unconditionally when the key is present in the body so the
        // client can clear it (full day) by sending null; COALESCE wouldn't allow that.
        const shiftProvided = 'shift' in req.body;

        const result = await queryWithRetry(
            `UPDATE staff_time_off SET
                start_date = COALESCE($1, start_date),
                end_date = COALESCE($2, end_date),
                type = COALESCE($3, type),
                shift = CASE WHEN $4::boolean THEN $5 ELSE shift END,
                notes = COALESCE($6, notes),
                approved = COALESCE($7, approved)
             WHERE id = $8 AND tenant_id = $9
             RETURNING *`,
            [startDate, endDate, type, shiftProvided, shift ?? null, notes, approved, id, req.tenantId!]
        );

        if (result.rows.length === 0) {
            return res.status(404).json({ error: 'Time off record not found' });
        }

        const row = result.rows[0];
        const timeOff = {
            id: row.id,
            staffId: row.staff_id,
            startDate: row.start_date,
            endDate: row.end_date,
            type: row.type,
            shift: row.shift,
            notes: row.notes,
            approved: row.approved,
            createdAt: row.created_at
        };

        // Broadcast
        const socketId = req.headers['x-socket-id'] as string;
        if (socketService) socketService.broadcastToAll(req.tenantId!, 'timeoff:updated', timeOff, socketId);

        res.json(timeOff);
    } catch (err) {
        console.error(err);
        res.status(500).json({ error: 'Internal server error' });
    }
});

