const startServer = async () => {
    try {
        // Start HTTP server
        const portNumber = Number(port);
        console.log(`Starting server on port ${portNumber}...`);

        httpServer.listen(portNumber, '0.0.0.0', () => {
            console.log(`✅ Server listening on port ${portNumber}`);

            // Initialize Socket.IO
            try {
                socketService = new SocketService(httpServer);
                console.log('✅ Socket.IO initialized');
                if (isPassepartoutAgentConfigured()) {
                    setupPassepartoutBridge(socketService.getIO());
                    console.log('✅ Passepartout agent bridge attivo su /pp-agent');
                }
            } catch (socketError) {
                console.error('Socket.IO initialization failed:', socketError);
            }

            // Initialize database schema in background, then backfill banquet reminders
            createSchema()
                .then(async () => {
                    console.log('✅ Database schema initialized');
                    // Le migration girano DOPO createSchema: la baseline
                    // congelata crea le tabelle, le migration le evolvono.
                    // Un errore qui non ferma il server (stessa filosofia di
                    // createSchema), ma va in log come errore: uno schema
                    // rimasto indietro è un incidente da vedere subito.
                    try {
                        await runMigrations();
                        console.log('✅ Database migrations up to date');
                    } catch (migErr) {
                        console.error('❌ Database migrations failed:', migErr);
                    }
                    // Warm della cache identità: i primi messaggi dopo il boot
                    // non devono uscire coi fallback se legal_config è compilato.
                    refreshBusinessIdentity(PUBLIC_TENANT_ID).catch(err =>
                        console.warn('Identity cache warm-up skipped:', (err as any)?.message || err));
                    try {
                        await RolePermissionService.warmUp();
                        console.log('✅ Role permission cache warmed up');
                    } catch (permErr) {
                        console.warn('Permission cache warm-up skipped:', permErr);
                    }
                    try {
                        const today = new Date().toISOString().substring(0, 10);
                        // Backfill di boot: nessuna richiesta in mano, il
                        // tenant si legge dalla riga del banchetto stesso.
                        const upcoming = await queryWithRetry(
                            "SELECT id, tenant_id, TO_CHAR(event_date, 'YYYY-MM-DD') AS event_date FROM banquet_menus WHERE event_date >= $1",
                            [today]
                        );
                        for (const row of upcoming.rows) {
                            await addBanquetToReminders(row.tenant_id, row.id, row.event_date);
                        }
                        if (upcoming.rows.length > 0) {
                            console.log(`✅ Backfilled kitchen reminder todos for ${upcoming.rows.length} upcoming banquet(s)`);
                        }
                    } catch (backfillErr) {
                        console.error('Banquet reminder backfill failed:', backfillErr);
                    }
                    try {
                        startRemindersScheduler();
                        console.log('✅ Reminders scheduler started (polls every 5 min, Europe/Rome)');
                    } catch (schedErr) {
                        console.error('Bread reminder scheduler failed to start:', schedErr);
                    }
                    try {
                        startBillSplitReconcileScheduler();
                        console.log('✅ Bill split reconcile scheduler started (60s)');
                    } catch (schedErr) {
                        console.error('Bill split reconcile scheduler failed to start:', schedErr);
                    }
                    try {
                        startPaymentRequestReconcileScheduler();
                        console.log('✅ Payment reconcile scheduler started (2 min)');
                    } catch (schedErr) {
                        console.error('Payment reconcile scheduler failed to start:', schedErr);
                    }
                    try {
                        // Fire-and-forget: the IMAP handshake can take seconds
                        // and we don't want to block schema-init callbacks.
                        // Da C4 è un supervisore: un listener per ogni tenant
                        // attivo con imap_enabled, non più solo il tenant 1.
                        startImapInboundService(() => socketService).catch((imapErr) => {
                            console.error('IMAP inbound service startup error:', imapErr);
                        });
                    } catch (imapErr) {
                        console.error('IMAP inbound service failed to start:', imapErr);
                    }
                })
                .catch((dbError) => {
                    console.error('Database initialization failed:', dbError);
                    console.error('Server will continue running, but database operations may fail');
                });
        }).on('error', (error) => {
            console.error('❌ Failed to start server:', error);
            process.exit(1);
        });
    } catch (error) {
        console.error('Failed to start server:', error);
        process.exit(1);
    }
};

startServer();